def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    return self.unpack('>H', 2)

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Construct the DISCARD payload
    payload = {"n": n, "qid": qid}

    # Recursive dehydration of the payload using the supplied hooks
    if dehydration_hooks:
        def _dehydrate(value):
            for typ, func in dehydration_hooks.items():
                if isinstance(value, typ):
                    try:
                        return func(value)
                    except Exception:
                        # If dehydration fails, keep original value
                        return value
            return value

        def _apply_dehydrate(obj):
            if isinstance(obj, dict):
                for k, v in obj.items():
                    obj[k] = _apply_dehydrate(v)
            elif isinstance(obj, list):
                for i, v in enumerate(obj):
                    obj[i] = _apply_dehydrate(v)
            else:
                return _dehydrate(obj)
            return obj

        _apply_dehydrate(payload)

    # Pack the payload using the connection's packer
    # Assuming the connection object implements a `pack` method
    encoded = self._connection.pack(payload)

    # Append the packed message to the output queue
    # Assuming the output queue is accessible as `_output_queue`
    self._output_queue.append(encoded)

    # Return a Response object that will process the record stream
    # and invoke any provided handlers.  The hydration_hooks are passed
    # to the Response so that it can correctly interpret the packed
    # data.  If the class does not have a Response implementation,
    # this line may be replaced with a suitable alternative.
    return Response(self._connection, hydration_hooks=hydration_hooks, **handlers)

