def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    nums = []
    for part in parts:
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            nums.append(int(num_str))
        else:
            nums.append(0)
    return tuple(nums)

