def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    # Extract the leading numeric part of the version string
    m = re.search(r"^(\d+(?:\.\d+)*)", s)
    if not m:
        return ()
    parts = m.group(1).split(".")
    try:
        return tuple(int(part) for part in parts)
    except ValueError:
        return ()

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Strip surrounding whitespace and split by dots
    parts = s.strip().split('.')
    nums: list[int] = []

    for part in parts:
        # Remove anything after a non-digit separator (e.g. '-alpha', 'beta1', etc.)
        core = part.split('-')[0]
        if core.isdigit():
            nums.append(int(core))

    # Return a 1-tuple containing zero if nothing could be parsed
    return tuple(nums) if nums else (0,)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    if not cmd:
        return cmd
    # Work with a mutable list while keeping the result a tuple
    cmd = list(cmd)
    script = cmd[0]

    # Only attempt to interpret shebangs for known script extensions
    _, ext = os.path.splitext(script.lower())
    if ext not in {'.py', '.pyw', '.bat', '.cmd'}:
        return tuple(cmd)

    if not os.path.isfile(script):
        return tuple(cmd)

    try:
        # Read first line of the script
        with open(script, 'rb') as f:
            first_line = f.readline().decode(errors='ignore')
    except Exception:
        return tuple(cmd)

    if not first_line.startswith('#!'):
        return tuple(cmd)

    # Parse interpreter component after "!".
    # It may contain arguments; we only care about the first token
    parts = first_line[2:].strip().split()
    if not parts:
        return tuple(cmd)

    interpreter_raw = parts[0]
    # Resolve to an absolute path if relative
    if not os.path.isabs(interpreter_raw):
        # Try the script's directory first
        script_dir = os.path.dirname(os.path.abspath(script))
        possible = os.path.join(script_dir, interpreter_raw)
        if os.path.isfile(possible):
            interpreter_raw = possible
        else:
            # Fallback: search PATH
            for dir_ in os.environ.get('PATH', '').split(os.pathsep):
                cand = os.path.join(dir_, interpreter_raw)
                if os.path.isfile(cand):
                    interpreter_raw = cand
                    break

    # Quote the interpreter if it contains spaces
    if ' ' in interpreter_raw:
        interpreter_raw = f'"{interpreter_raw}"'

    # Build new command tuple: interpreter, script, rest args
    new_cmd = (interpreter_raw, script, *cmd[1:])
    return tuple(new_cmd)

