def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time‑to‑live (TTL) value.
    """
    def decorator(func):
        cache = {}
        lru = []

        def make_key(args, kwargs):
            key = args
            if kwargs:
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in items)
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            if key in cache:
                val, expire = cache[key]
                # Check TTL
                if expire is None or expire > now:
                    # Move to end of LRU list
                    try:
                        lru.remove(key)
                    except ValueError:
                        pass
                    lru.append(key)
                    return val
                # Expired: remove
                del cache[key]
                try:
                    lru.remove(key)
                except ValueError:
                    pass

            # Compute new value
            val = func(*args, **kwargs)
            expire = None if ttl <= 0 else now + ttl
            cache[key] = (val, expire)
            lru.append(key)

            # Enforce maxsize
            if maxsize > 0 and len(cache) > maxsize:
                oldest = lru.pop(0)
                cache.pop(oldest, None)

            return val

        def cache_clear():
            nonlocal cache, lru
            cache = {}
            lru = []

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

