def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if cls in seen:
            continue
        # Skip if another class in the list is a subclass of this one
        if any(other is not cls and issubclass(other, cls) for other in classes):
            continue
        seen.add(cls)
        result.append(cls)
    return result

