def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    cls = type(self)
    if all:
        # Collect attributes from class and all its bases (except object)
        attrs = {}
        for base in reversed(cls.__mro__):
            if base is object:
                continue
            attrs.update(base.__dict__)
    else:
        # Only attributes defined directly on the class
        attrs = cls.__dict__

    # Return a sorted list of attribute names that are not private and not methods
    return sorted(
        [name
         for name, value in attrs.items()
         if not name.startswith('_') and not callable(value)]
    )

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    import inspect
    # Determine which classes to scan: the current class only, or the full MRO
    classes = [self.__class__]
    if all:
        classes = inspect.getmro(self.__class__)

    # Collect attribute names, skipping dunder and callables
    names = set()
    for cls in classes:
        if cls is object:
            continue
        for name, value in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if callable(value):
                continue
            names.add(name)

    # Return a sorted list for consistency
    return sorted(names)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    def _is_attribute(name, cls):
        attr = getattr(cls, name, None)
        return not name.startswith('_') and not callable(attr)

    # Attributes defined directly on the class
    attr_names = [n for n in vars(self.__class__).keys() if _is_attribute(n, self.__class__)]

    if all:
        # Include attributes inherited from parent classes
        for base in self.__class__.__mro__[1:]:
            for n in vars(base).keys():
                if n not in attr_names and _is_attribute(n, base):
                    attr_names.append(n)

    return attr_names

