def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # reset context
    self.context = {}

    # reinitialize bins
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # keep the same number of bins but fill with the initial value
        bin_count = len(self.bins) if hasattr(self, "bins") else 0
        self.bins = [self.initial_value] * bin_count
    else:
        self.bins = self.make_bins()

    # reset counts if they exist
    if hasattr(self, "counts"):
        self.counts = [0] * len(self.bins)

    # reset other bookkeeping attributes if they exist
    if hasattr(self, "total_count"):
        self.total_count = 0
    if hasattr(self, "min_value"):
        self.min_value = None
    if hasattr(self, "max_value"):
        self.max_value = None
    if hasattr(self, "start_time_stamp_msec"):
        self.start_time_stamp_msec = None
    if hasattr(self, "end_time_stamp_msec"):
        self.end_time_stamp_msec = None

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context
    self.context = {}
    # Reinitialize bins
    if hasattr(self, 'make_bins') and callable(self.make_bins):
        self.bins = self.make_bins()
    else:
        self.bins = {}
    # If an initial value is set, fill bins with it
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        for key in self.bins:
            self.bins[key] = self.initial_value

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the error array for the specified coordinate
    errors = getattr(self, "errors", {}).get(coord_name)
    if errors is None:
        return []

    # Convert to a NumPy array (assumes it is array‑like)
    try:
        errors_arr = np.asarray(errors)
    except Exception:
        raise TypeError(f"Error data for coordinate '{coord_name}' is not array‑like")

    # Return indices where the error flag is truthy
    return np.where(errors_arr)[0].tolist()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Determine the name of the corresponding error variable.
    err_name = f"{coord_name}_err"
    if err_name not in self._variables:
        # No corresponding error variable; return empty array.
        return np.array([], dtype=int)

    err_var = self._variables[err_name]
    # Extract numeric values; support DataArray-like objects with `values` attribute.
    try:
        data = err_var.values
    except AttributeError:
        data = np.array(err_var)

    # Flatten in case of multi‑dimensional data.
    data = np.asarray(data).ravel()

    # Determine mask: for numeric data, assume non‑zero implies an error.
    # For boolean or mask data, use truthiness directly.
    if np.issubdtype(data.dtype, np.number):
        mask = data != 0
    else:
        mask = data

    # Return zero‑based indices where errors are present.
    return np.where(mask)[0]

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to retrieve the coordinate variable from the instance
    coord = self._variables.get(coord_name)
    if coord is None:
        return []

    # Find the error array associated with this coordinate.
    # Priority order:
    #  1. Attribute 'err' on the coordinate object.
    #  2. Variable named '{coord_name}_err' in the object's variable dict.
    err = getattr(coord, "err", None)
    if err is None:
        err = self._variables.get(f"{coord_name}_err")

    if err is None:
        return []

    # Convert error data to a NumPy array (if it isn’t one already).
    try:
        err_arr = np.asarray(err)
    except Exception:
        return []

    # Determine indices where the error is finite and non‑zero.
    idx = np.where(np.isfinite(err_arr) & (err_arr != 0))[0]
    return idx.tolist()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to retrieve from a dedicated error indices dictionary
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        idx = self._err_indices.get(coord_name)
        if idx is not None:
            return idx
    # Fallback: look for an 'errors' dictionary attribute
    if hasattr(self, "errors") and isinstance(self.errors, dict):
        idx = self.errors.get(coord_name)
        if idx is not None:
            return idx
    # Another fallback: look for an attribute named like <coord_name>_err
    err_attr = getattr(self, f"{coord_name}_err", None)
    if err_attr is not None:
        # If the error attribute has an 'indices' attribute, return it
        try:
            return getattr(err_attr, "indices", [])
        except Exception:
            pass
    # If nothing found, return an empty list to indicate no error indices
    return []

def _get_err_indices(self, coord_name):
    """
    Get error indices corresponding to a coordinate.

    Returns a list of indices that represent error flags or error values
    associated with ``coord_name``.  The method looks for an
    ``*_err`` variable that holds these indices, falling back to
    attributes of the coordinate variable itself if present.  If no
    error information is found an empty list is returned.

    Args:
        coord_name: name of the coordinate to look for error indices.

    Returns:
        list: indices where errors are defined for the coordinate.
    """
    # preferred: look for a dedicated error array named ``coord_name_err``.
    err_var_name = f"{coord_name}_err"

    # 1. Check an error mapping that may be stored on the instance
    if hasattr(self, "_errors") and isinstance(self._errors, dict):
        if err_var_name in self._errors:
            return list(self._errors[err_var_name])

    # 2. Look inside the coordinate dictionary if one exists
    if hasattr(self, "coords") and isinstance(self.coords, dict):
        # a. error indices stored as an attribute on the coordinate object
        coord_obj = self.coords.get(coord_name)
        if coord_obj is not None:
            if hasattr(coord_obj, "error_indices"):
                return list(coord_obj.error_indices)
            # common pattern: coordinate has an associated error variable
            if hasattr(coord_obj, "err"):
                return list(coord_obj.err)
            # fall back to look for a matching *err key inside the coordinate object
            if isinstance(coord_obj, dict) and err_var_name in coord_obj:
                return list(coord_obj[err_var_name])

    # 3. Search instance attributes for a matching error variable
    if hasattr(self, err_var_name):
        return list(getattr(self, err_var_name))

    # 4. As a last resort, search attrs (if a Dataset/Group attributes are used)
    if hasattr(self, "attrs") and isinstance(self.attrs, dict):
        if err_var_name in self.attrs:
            return list(self.attrs[err_var_name])

    # No error indices found
    return []

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    bins = np.asarray(bins)
    # If edges are None or empty, return the sum of bins
    if edges is None or len(edges) == 0:
        return np.sum(bins)
    # Handle 1‑D edges
    edges_arr = np.asarray(edges)
    if edges_arr.ndim == 1:
        widths = np.diff(edges_arr)
        return np.sum(bins * widths)
    # Multi‑dimensional histogram: edges is a sequence of 1‑D edge arrays
    if isinstance(edges, (list, tuple)):
        widths = [np.diff(e) for e in edges]
        # create weight grid that can broadcast to the shape of bins
        weight = np.multiply.reduce(
            [w.reshape([1] * i + [-1] + [1] * (len(widths) - i - 1))
             for i, w in enumerate(widths)]
        )
        return np.sum(bins * weight)
    # Fallback: treat edges as a flat sequence
    widths = np.diff(edges_arr.ravel())
    return np.sum(bins * widths)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Accept a single FillRequest instance
    if isinstance(seq, FillRequest):
        return True

    # Exclude Source sequences outright
    if isinstance(seq, Source):
        return False

    # Strings and bytes are iterables but not valid sequences here
    if isinstance(seq, (str, bytes)):
        return False

    # Attempt to iterate over the sequence
    try:
        iterator = iter(seq)
    except TypeError:
        return False

