def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dict")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dict")

    def _diff(d1_local, d2_local, depth):
        result = {}
        for key, val1 in d1_local.items():
            if key not in d2_local:
                result[key] = val1
            else:
                val2 = d2_local[key]
                if isinstance(val1, dict) and isinstance(val2, dict):
                    # Decide whether to recurse
                    if depth == -1 or depth > 0:
                        sub_depth = -1 if depth == -1 else depth - 1
                        sub_diff = _diff(val1, val2, sub_depth)
                        if sub_diff:
                            result[key] = sub_diff
                else:
                    if val1 != val2:
                        result[key] = val1
        return result

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError('difference expects both arguments to be dictionaries')

    # Base case: if recursion depth reached and we still have dictionaries,
    # treat them as atomic objects and rely on equality comparison.
    if level == 0:
        # We will not descend into subdicts; include the value from d1 only
        # if it differs from the corresponding value in d2.
        diff = {}
        for key, val in d1.items():
            if key not in d2 or val != d2[key]:
                diff[key] = val
        return diff

    diff = {}
    for key, val in d1.items():
        if key not in d2:
            diff[key] = val
            continue

        val2 = d2[key]

        # If both values are dicts, recurse
        if isinstance(val, dict) and isinstance(val2, dict):
            new_level = level - 1 if level > 0 else -1
            subdiff = difference(val, val2, new_level)
            # Only include the key if subdiff is non-empty
            if subdiff:
                diff[key] = subdiff
        else:
            # For non-dict values, include if they differ
            if val != val2:
                diff[key] = val

    return diff

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """

    # Helper function to decide if two values are equal
    def _eq(val1, val2):
        try:
            return val1 == val2
        except Exception:
            return False

    result = {}

    # Determine recursion depth handling
    # level == -1 --> infinite, otherwise limit depth
    recurse_next = level > 0

    for key, val in d1.items():
        if key not in d2:
            # Key missing in d2: include it
            # If val is a dict, we return a shallow copy to avoid accidental
            # modification of the original structure; nested dicts will be
            # handled by recursion only if recursion occurs.
            if isinstance(val, dict):
                # If we are not recursing into it, just copy it
                result[key] = val.copy()
            else:
                result[key] = val
        else:
            val2 = d2[key]
            # If both values are dicts and we are allowed to recurse
            if isinstance(val, dict) and isinstance(val2, dict) and recurse_next:
                sub_diff = difference(val, val2, level - 1 if level > 0 and level != -1 else -1)
                if sub_diff:
                    result[key] = sub_diff
            else:
                # For level 0 or non-dict values: include if values differ
                if not _eq(val, val2):
                    result[key] = val

    return result

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    import copy

    def _diff(a, b, depth):
        """Recursively compute difference between a and b up to given depth."""
        # depth == -1 means infinite
        res = {}
        for k, v in a.items():
            if k not in b:
                # key missing entirely in b -> take this entry
                if isinstance(v, dict):
                    # avoid copying the original dict if no further recursion
                    res[k] = v
                else:
                    res[k] = copy.deepcopy(v)
                continue

            # key present in both
            w = b[k]
            if v == w:
                # no difference
                continue

            # values differ
            if isinstance(v, dict) and isinstance(w, dict):
                # if we are allowed to recurse further
                if depth == -1 or depth > 1:
                    sub = _diff(v, w, None if depth == -1 else depth - 1)
                    if sub:
                        res[k] = sub
                        continue
            # if we reach this point, either we don't recurse or sub-diff empty
            if isinstance(v, dict):
                # fallback: include entire dict from a
                res[k] = v
            else:
                res[k] = copy.deepcopy(v)
        return res

    return _diff(d1, d2, level)

