def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Ensure coordinate matches number of dimensions
        if len(coord) != len(self.edges):
            raise ValueError(f"coord length {len(coord)} does not match number of dimensions {len(self.edges)}")

        # Compute bin index for each dimension
        indices = []
        for c, edges in zip(coord, self.edges):
            # Skip if coordinate is outside the binning range
            if c < edges[0] or c >= edges[-1]:
                return  # outside histogram edges, ignore
            # Find the index of the bin such that edges[i] <= c < edges[i+1]
            idx = np.searchsorted(edges, c, side='right') - 1
            indices.append(idx)

        # Convert multi-dimensional index to flat index if histogram data is stored in a flat array
        if hasattr(self, 'data') and self.data.ndim > 1:
            # assume self.data is a numpy array with shape derived from edges
            flat_index = np.ravel_multi_index(tuple(indices), self.data.shape)
            self.data.flat[flat_index] += weight
        else:
            # Fall back to dictionary-based storage
            key = tuple(indices)
            if hasattr(self, 'storage') and isinstance(self.storage, dict):
                self.storage[key] = self.storage.get(key, 0) + weight
            else:
                # If storage is not defined, initialize a dictionary
                self.storage = {key: weight} if weight != 0 else {}

        return None

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Make sure the coordinate is a number
    try:
        x = float(coord)
    except (TypeError, ValueError):
        # If we cannot cast to float, ignore silently
        return

    # Ensure the histogram contains the required attributes
    if not hasattr(self, 'edges'):
        raise AttributeError("Histogram object missing 'edges' attribute")
    if not hasattr(self, 'bins'):
        raise AttributeError("Histogram object missing 'bins' attribute")

    edges = np.asarray(self.edges)
    # Check if coordinate is inside the binning range
    if x < edges[0] or x >= edges[-1]:
        return

    # Find the index of the bin that contains the coordinate
    idx = np.searchsorted(edges, x, side='right') - 1

    # Update the bin count with the supplied weight
    try:
        self.bins[idx] += weight
    except Exception as exc:
        raise ValueError(f"Unable to update bin {idx} with weight {weight}: {exc}") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    # Regular expressions for keys and values
    KEY_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')
    VALUE_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')

    errors = []

    for k, v in labels.items():
        # Check key type
        if not isinstance(k, (str, bytes)):
            errors.append({str(k): 'expected string or bytes-like object'})
        else:
            # Check key regex validity
            if not KEY_REGEX.match(k):
                errors.append({k: f"Label key '{k}' does not match the regex [{KEY_REGEX.pattern}]"})

        # Check value
        if isinstance(v, list):
            for item in v:
                if not isinstance(item, (str, bytes)):
                    errors.append({f"['{item}']": 'expected string or bytes-like object'})
                else:
                    if not VALUE_REGEX.match(item):
                        errors.append({f"['{item}']": f"Label value '{item}' does not match the regex [{VALUE_REGEX.pattern}]"})
        else:
            if not isinstance(v, (str, bytes)):
                errors.append({str(k): 'expected string or bytes-like object'})
            else:
                if not VALUE_REGEX.match(v):
                    errors.append({k: f"Label value '{v}' does not match the regex [{VALUE_REGEX.pattern}]"})

    if errors:
        raise ValidationError(errors)

