                    processed_list.append(generate_default_observer_schema_dict(item, first_level=first_level))
                else:
                    processed_list.append(None)
            result[key] = processed_list
        else:
            # Primitive value: replace with None unless it's an identifying field at the top level
            if first_level and key in {"apiVersion", "kind"}:
                result[key] = value
            elif first_level and key == "metadata" and isinstance(value, dict):
                # Keep name and namespace under metadata if present
                sub = {}
                for subkey in ("name", "namespace"):
                    if subkey in value:
                        sub[subkey] = value[subkey]
                result[key] = sub
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Helper to determine if an object is a mapping
    def is_mapping(obj):
        from collections.abc import Mapping

        return isinstance(obj, Mapping)

    # Treat 'last_applied_manifest' as a dict for updates
    if not is_mapping(last_applied_manifest):
        # If it is a list, wrap it into a dict under a key that represents the
        # resource type or use an empty dict as placeholder.
        # In typical usage, the manifest will be a dict; but we guard against
        # unexpected input.
        last_applied_manifest = {}

    # Recursive worker
    def _update(dest, schema, src):
        if is_mapping(schema):
            # Schema is a dict of field -> sub-schema
            for key, subschema in schema.items():
                if key in dest:
                    # Dest already has this key; if sub-schema is nested, recurse
                    if is_mapping(subschema) or isinstance(subschema, (list, tuple)):
                        _update(dest[key], subschema, src.get(key, {}))
                else:
                    # Initialize from src if exists
                    if key in src:
                        if is_mapping(subschema) or isinstance(subschema, (list, tuple)):
                            # For nested structures, create an empty mapping and recurse
                            # Use a dict or list based on subschema type
                            if isinstance(subschema, dict):
                                dest[key] = {}
                            else:
                                dest[key] = {}
                            _update(dest[key], subschema, src.get(key, {}))
                        else:
                            dest[key] = src[key]
        elif isinstance(schema, (list, tuple)):
            # Schema is a list: each element can be a key (string) or a nested dict
            for item in schema:
                if isinstance(item, str):
                    if item not in dest and item in src:
                        dest[item] = src[item]
                elif is_mapping(item):
                    for key, subschema in item.items():
                        if key in dest:
                            if is_mapping(subschema) or isinstance(subschema, (list, tuple)):
                                _update(dest[key], subschema, src.get(key, {}))
                        else:
                            if key in src:
                                if is_mapping(subschema) or isinstance(subschema, (list, tuple)):
                                    if isinstance(subschema, dict):
                                        dest[key] = {}
                                    else:
                                        dest[key] = {}
                                    _update(dest[key], subschema, src.get(key, {}))
                                else:
                                    dest[key] = src[key]
                else:
                    # Unsupported item type; ignore
                    continue
        else:
            # Unsupported schema type; ignore
            pass

    _update(last_applied_manifest, observer_schema, response)
    # No explicit return; last_applied_manifest is modified in place.

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    This function goes through all observed fields, and initializes their
    value in ``last_applied_manifest`` if they are not yet present.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema``.
        response (list): partial response from the Kubernetes API.
    """
    if not isinstance(observer_schema, list) or not isinstance(response, list):
        return

    for schema_item in observer_schema:
        # Extract field name from the schema item
        if isinstance(schema_item, dict):
            field_name = schema_item.get("name")
            nested_schema = schema_item.get("schema")
        else:
            field_name = schema_item
            nested_schema = None

        if not field_name:
            continue

        # Find the response sub‑obj that matches this field name
        resp_item = next(
            (r for r in response if isinstance(r, dict) and r.get("name") == field_name),
            None,
        )
        if resp_item is None:
            continue

        # Skip if already present in the last_applied_manifest
        if any(
            isinstance(m, dict) and m.get("name") == field_name
            for m in last_applied_manifest
        ):
            continue

        # Handle nested structures recursively
        if isinstance(resp_item, dict):
            value = resp_item.get("value")
            if isinstance(value, dict) and nested_schema:
                new_val = {}
                update_last_applied_manifest_dict_from_resp(
                    new_val, nested_schema, value
                )
                resp_item = {"name": field_name, "value": new_val}
            elif isinstance(value, list) and nested_schema:
                new_val = []
                update_last_applied_manifest_list_from_resp(
                    new_val, nested_schema, value
                )
                resp_item = {"name": field_name, "value": new_val}

        last_applied_manifest.append(resp_item)

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field {key!r} not present in response")

        resp_value = response[key]

        # If the response value is a list, delegate to the list handler
        if isinstance(resp_value, list):
            # Ensure the key exists in the manifest as a list
            if key not in last_applied_manifest or not isinstance(
                last_applied_manifest[key], list
            ):
                last_applied_manifest[key] = []

            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], sub_schema, resp_value
            )
        # If the response value is a dict, recurse into it
        elif isinstance(resp_value, dict):
            if key not in last_applied_manifest or not isinstance(
                last_applied_manifest[key], dict
            ):
                last_applied_manifest[key] = {}

            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, resp_value
            )
        # Primitive scalar value
        else:
            last_applied_manifest[key] = resp_value

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the manifest which is a list of resource dicts
    manifest = getattr(app.spec, 'manifest', [])
    # Ensure the observer_schema dict exists
    observer = getattr(app.spec, 'observer_schema', None)
    if observer is None:
        observer = {}
        setattr(app.spec, 'observer_schema', observer)
    for resource in manifest:
        kind = resource.get('kind')
        if not kind:
            continue
        # Skip if a custom observer schema is already defined for this kind
        if kind in observer:
            continue
        # Create a simple default observer schema for this kind
        observer[kind] = {
            "$schema": "http://json-schema.org/draft-04/schema#",
            "type": "object",
            "properties": {}
        }
    return observer

def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.
        """
        # Determine the inn and out parameter styles known to the SQLParams helper.
        in_style = getattr(self, "SQLParams", None).in_style if getattr(self, "SQLParams", None) else None
        out_style = getattr(self, "SQLParams", None).out_style if getattr(self, "SQLParams", None) else None

        # Decide how many parameters we receive.
        is_mapping = isinstance(params, Mapping)
        is_sequence = isinstance(params, Sequence) and not isinstance(params, (str, bytes))

        if in_style in ("named", "format"):
            if not is_mapping:
                raise ValueError("Expected a mapping for named-format in‑style parameters")

            # Find all named placeholders in the input query:
            # supports :name or %(name)s stylistics.
            placeholder_re = re.compile(r"(:\w+|%\(\w+\)s)")
            parts = []
            new_params = {}
            index = 0
            for m in placeholder_re.finditer(sql):
                parts.append(sql[index : m.start()])
                placeholder = m.group()

                # Figure out the key that maps into the provided dict.
                if placeholder.startswith("%("):
                    key = placeholder[2:-2]  # remove "%(" and ")s"
                else:
                    key = placeholder[1:]   # remove leading ':'

                # Determine the replacement placeholder based on out_style.
                if out_style == "qmark":
                    parts.append("?")
                    new_params[key] = params[key]
                elif out_style == "named":
                    parts.append(f":{key}")
                    new_params[key] = params[key]
                elif out_style == "format":
                    parts.append("%s")
                    new_params[key] = params[key]
                else:
                    parts.append("?")
                    new_params[key] = params[key]
                index = m.end()

            parts.append(sql[index:])  # tail of the string
            new_sql = "".join(parts)

            if out_style == "named":
                formatted_args = new_params
            else:
                formatted_args = list(new_params.values())
            return new_sql, formatted_args

        else:
            # Ordinal style: placeholders are %s or ?
            if not is_sequence:
                raise ValueError("Expected a sequence for ordinal in‑style parameters")

            if out_style == "qmark":
                new_sql = re.sub(r"(%s|\?)", "?", sql)
                return new_sql, list(params)

            if out_style == "named":
                # convert ? or %s to :1, :2, ...
                new_parts = []
                index = 0
                for m in re.finditer(r"(%s|\?)", sql):
                    new_parts.append(sql[index : m.start()])
                    new_parts.append(f":{len(new_parts) + 1}")
                    index = m.end()
                new_parts.append(sql[index:])
                new_sql = "".join(new_parts)
                args_dict = {i + 1: val for i, val in enumerate(params)}
                return new_sql, args_dict

            if out_style == "format":
                new_sql = re.sub(r"(%s|\?)", "%s", sql)
                return new_sql, list(params)

            # Default: leave as is
            return sql, list(params)

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        try:
            # Basic existence and directory check
            if not path or not os.path.exists(path):
                return False
            if not os.path.isdir(path):
                return False

            # Minimal OCFL structure: expect a ".ocfl" directory with a "current" file
            ocfl_dir = os.path.join(path, ".ocfl")
            if os.path.isdir(ocfl_dir):
                current_file = os.path.join(ocfl_dir, "current")
                if os.path.isfile(current_file):
                    return True

            # Fallback: accept non-empty directories as potentially valid
            return bool(os.listdir(path))
        except Exception:
            return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        return False
    try:
        # Ensure path exists and is a directory
        if not os.path.isdir(path):
            return False
        # OCFL objects must contain a `.ocfl-root` directory
        ocfl_root = os.path.join(path, ".ocfl-root")
        if not os.path.isdir(ocfl_root):
            return False
        # Basic sanity: object ID directory should exist inside `.ocfl-root`
        obj_id_dir = os.path.join(ocfl_root, "objects")
        if not os.path.isdir(obj_id_dir):
            return False
        # If all checks pass, consider the object valid
        return True
    except Exception:
        # Any error during validation results in False
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import ocfl
    except Exception:
        return False

    try:
        # If the ocfl module provides a standalone validate function
        if hasattr(ocfl, "validate"):
            result = ocfl.validate(path)
            if isinstance(result, dict):
                # Assume dict contains an 'errors' key for validation errors
                return len(result.get("errors", [])) == 0
            return bool(result)

        # If the ocfl module has an OcflObject class, try to load and validate the object
        if hasattr(ocfl, "OcflObject"):
            obj = ocfl.OcflObject.from_path(path)
            if hasattr(obj, "validate"):
                return obj.validate()
            # If no validate method, assume object was loaded successfully
            return True
    except Exception:
        return False

    return False

