    if log is None:
        return ''

    # Normalise to an iterable of strings
    if isinstance(log, (str, bytes)):
        entries = [log if isinstance(log, str) else log.decode('utf-8')]
    elif isinstance(log, dict):
        entries = [f"{k}: {v}" for k, v in log.items()]
    else:
        try:
            entries = list(log)
        except TypeError:
            entries = [str(log)]

    # Prefix each entry and join
    prefixed = [f"{prefix}{entry}" for entry in entries]
    return "\n".join(prefixed)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Use the `log` attribute to store validation entries. If the attribute
    # does not exist or is empty, return an empty string.
    if not hasattr(self, "log") or not self.log:
        return ""
    lines = []
    for entry in self.log:
        # Prefer a readable message if the entry is a dictionary.
        if isinstance(entry, dict):
            message = entry.get("message") or entry.get("text") or str(entry)
        else:
            message = str(entry)
        lines.append(prefix + message)
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine which spec version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        # Acceptable type identifiers and map them to internal spec versions
        type_to_spec = {"v1": "v1", "v2": "v2"}
        if isinstance(type_val, str) and type_val.lower() in type_to_spec:
            spec_version = type_to_spec[type_val.lower()]
        else:
            spec_version = self.spec_version

    # Basic required fields for all inventories
    required_fields = ["name", "data"]
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Missing required field '{field}' in inventory")

    # Version specific validation
    if spec_version == "v1":
        if "metadata" not in inventory:
            raise ValueError("v1 inventory must contain 'metadata'")
        if not isinstance(inventory["metadata"], dict):
            raise ValueError("'metadata' must be a dictionary")
    elif spec_version == "v2":
        if "meta" not in inventory:
            raise ValueError("v2 inventory must contain 'meta'")
        if not isinstance(inventory["meta"], dict):
            raise ValueError("'meta' must be a dictionary")
    else:
        raise ValueError(f"Unsupported specification version '{spec_version}'")

    # All checks passed; return the validated inventory
    return inventory

def validate(self, inventory, extract_spec_version=False):
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dict")
    # 1. If requested, try to determine spec version from the inventory type field
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            for part in type_val.split():
                part_clean = part.replace(".", "", 1)
                if part_clean.isdigit() or (part_clean.replace(".", "", 1).isdigit() and part_clean.count(".") <= 1):
                    self.spec_version = part_clean
                    break
    # 2. Validate required fields if a list of required fields is provided on the validator
    required = getattr(self, "required_fields", [])
    for field in required:
        if field not in inventory:
            raise ValueError(f"Missing required field: {field}")
    # 3. Validate each field against a spec if one is provided
    field_specs = getattr(self, "field_specs", {})
    for key, value in inventory.items():
        spec = field_specs.get(key)
        if spec is not None:
            if isinstance(spec, type):
                if not isinstance(value, spec):
                    raise ValueError(
                        f"Field '{key}' expected type {spec.__name__}, got {type(value).__name__}"
                    )
            elif callable(spec):
                if not spec(value):
                    raise ValueError(f"Field '{key}' failed custom validation")
    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a container we can work with
    if not isinstance(inventory, (dict, list)):
        raise TypeError(
            f"inventory must be a dict or list, got {type(inventory).__name__}"
        )

    # Determine which spec version to use
    version_to_use = self.spec_version
    if extract_spec_version and isinstance(inventory, dict):
        type_val = inventory.get("type")
        if isinstance(type_val, str) and type_val in getattr(
                self, "spec_versions", []
        ):
            version_to_use = type_val

    # Temporarily set the spec version if it changes
    original_version = getattr(self, "spec_version", None)
    if version_to_use != original_version:
        self.spec_version = version_to_use

    try:
        # Assume the actual validation logic is implemented in _do_validate
        # which uses self.spec_version internally.  If such a method doesn't
        # exist, fall back to a simple no-op that just returns the inventory.
        if hasattr(self, "_do_validate") and callable(self._do_validate):
            validated_inventory = self._do_validate(inventory)
        else:
            validated_inventory = inventory
    finally:
        # Restore the original spec version regardless of success or failure
        if original_version is not None:
            self.spec_version = original_version

    return validated_inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Interpret manifest_files as a mapping from digest -> filename or a list of digests.
    if isinstance(manifest_files, dict):
        present_digests = set(manifest_files.keys())
    else:
        present_digests = set(manifest_files)

    used_digests = set(digests_used)

    # Digests that are present in the manifest but not marked as used.
    missing_used = present_digests - used_digests
    if missing_used:
        raise ValueError(
            f"Manifest digests missing from used set: {sorted(missing_used)}"
        )

    # Digests that are marked as used but not present in the manifest.
    unused_present = used_digests - present_digests
    if unused_present:
        raise ValueError(
            f"Used digests not found in manifest: {sorted(unused_present)}"
        )

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise ValueError("manifest_files should be a dict mapping filenames to digests")

    manifest_digests = set(manifest_files.values())
    used_digests = set(digests_used)

    missing_in_manifest = used_digests - manifest_digests
    if missing_in_manifest:
        raise ValueError(
            f"Used digests {', '.join(sorted(missing_in_manifest))} not found in manifest"
        )

    missing_in_used = manifest_digests - used_digests
    if missing_in_used:
        raise ValueError(
            f"Digests {', '.join(sorted(missing_in_used))} present in manifest but not used"
        )

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.
        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, type(self)):
            raise TypeError('prior must be an InventoryValidator instance')

        # If a version attribute exists, the prior must be older
        if hasattr(self, 'version') and hasattr(prior, 'version'):
            if prior.version >= self.version:
                raise ValueError(
                    f'Prior inventory (version {prior.version}) must be older than the current inventory (version {self.version})'
                )

        # Check that the expected prior name matches the actual prior name
        expected_prior_name = getattr(self, 'prior_name', None)
        actual_prior_name = getattr(prior, 'name', None)
        if expected_prior_name and actual_prior_name != expected_prior_name:
            raise ValueError(
                f'Prior inventory name "{actual_prior_name}" does not match the expected prior name "{expected_prior_name}"'
            )

        # Ensure that every component present in the prior is also present in the current inventory.
        for attr in ('species', 'parameters', 'constraints'):
            prior_set = set(getattr(prior, attr, []))
            current_set = set(getattr(self, attr, []))
            missing = prior_set - current_set
            if missing:
                raise ValueError(
                    f'Current inventory is missing {attr} present in prior: {missing}'
                )

        # Check that the values for shared keys are identical
        for attr in ('species', 'parameters'):
            prior_dict = getattr(prior, attr, {})
            current_dict = getattr(self, attr, {})
            for key, value in prior_dict.items():
                if key in current_dict and current_dict[key] != value:
                    raise ValueError(
                        f'Value mismatch for {attr} "{key}": prior={value} current={current_dict[key]}'
                    )

        return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure the prior is the same type of validator
    if not isinstance(prior, type(self)):
        raise TypeError(f'prior must be an instance of {type(self).__name__}, got {type(prior).__name__}')

    # Both objects should expose a version attribute
    if not hasattr(self, 'version') or not hasattr(prior, 'version'):
        raise AttributeError("Both the current and prior validators must have a 'version' attribute")

    # The prior version must be strictly older than the current version
    if prior.version >= self.version:
        raise ValueError(
            f"Prior version ({prior.version}) must be older than current version ({self.version})"
        )

    # If the validator stores its items in a dictionary named 'inventory', ensure the prior
    # does not contain items that are not present in the current inventory.
    if hasattr(self, 'inventory') and hasattr(prior, 'inventory'):
        current_keys = set(self.inventory.keys())
        prior_keys = set(prior.inventory.keys())
        missing = prior_keys - current_keys
        if missing:
            raise ValueError(
                f"Prior validator contains extra keys that are missing in the current inventory: {missing}"
            )

    # If the validator keeps a list or dict of models/items in 'items', we can rudimentarily
    # verify that the prior does not reference newer objects
    if hasattr(self, 'items') and hasattr(prior, 'items'):
        for key, curr_item in self.items.items():
            if key in prior.items:
                prior_item = prior.items[key]
                if getattr(prior_item, 'version', None) >= getattr(curr_item, 'version', None):
                    raise ValueError(
                        f"Item '{key}' in prior has a version ({getattr(prior_item, 'version')}) "
                        f"that is not older than the current version ({getattr(curr_item, 'version')})"
                    )

    # If all checks pass, the prior is considered valid
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # Species lists must match
    if set(self.species) != set(prior.species):
        raise ValueError(
            "Species mismatch between current and prior inventories:\n"
            f"  Current: {sorted(self.species)}\n"
            f"  Prior:   {sorted(prior.species)}"
        )

    # Reaction count must match
    if len(self.reactions) != len(prior.reactions):
        raise ValueError(
            f"Number of reactions differs: current={len(self.reactions)}, "
            f"prior={len(prior.reactions)}"
        )

    # Compare each corresponding reaction
    for idx, (curr_reac, prior_reac) in enumerate(zip(self.reactions, prior.reactions)):
        if getattr(curr_reac, "name", None) != getattr(prior_reac, "name", None):
            raise ValueError(
                f"Reaction name mismatch at index {idx}:\n"
                f"  Current: {getattr(curr_reac, 'name', None)}\n"
                f"  Prior:   {getattr(prior_reac, 'name', None)}"
            )

        # If both reactions expose stoichiometry matrices, compare shapes
        curr_mat = getattr(curr_reac, "stoichiometry_matrix", None)
        prior_mat = getattr(prior_reac, "stoichiometry_matrix", None)
        if curr_mat is not None and prior_mat is not None:
            if curr_mat.shape != prior_mat.shape:
                raise ValueError(
                    f"Stoichiometry matrix shape mismatch in reaction '{curr_reac.name}': "
                    f"current={curr_mat.shape}, prior={prior_mat.shape}"
                )

    # Parameters must match
    if set(self.parameters) != set(prior.parameters):
        raise ValueError(
            "Parameter list mismatch between current and prior inventories:\n"
            f"  Current: {sorted(self.parameters)}\n"
            f"  Prior:   {sorted(prior.parameters)}"
        )

    # Transformations (if any) must be identical
    curr_trans = getattr(self, "transformations", None)
    prior_trans = getattr(prior, "transformations", None)
    if curr_trans is not None or prior_trans is not None:
        if curr_trans != prior_trans:
            raise ValueError(
                f"Transformations differ between current and prior inventories:\n"
                f"  Current: {curr_trans}\n"
                f"  Prior:   {prior_trans}"
            )
    # All checks passed; method completes without error.

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    # Normalise version to string for compatible comparison
    target = str(version)
    logical_map = {}

    # Iterate over all versions in the inventory
    for ver, state in inventory.items():
        try:
            # Include this version only if it is the target or later
            if ver >= target:
                for logical_path, files in state.items():
                    logical_map.setdefault(logical_path, set()).update(files)
        except Exception:
            # If the version key is not comparable (e.g., a non-string), skip it
            continue

    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    for logical_path, details in inventory.items():
        # Expect `details` to be a mapping of version -> content file(s)
        if not isinstance(details, dict):
            continue

        # 1. Try direct lookup of the requested version
        target = details.get(version)

        # 2. If the mapping is nested under a 'content_files' key, look there
        if target is None and isinstance(details.get("content_files"), dict):
            target = details["content_files"].get(version)

        # If still not found, skip this logical path
        if target is None:
            continue

        # Normalize into a set of content files
        if isinstance(target, (list, set, tuple)):
            files = set(target)
        else:
            files = {target}

        # Include duplicates contained in later versions of the same logical path
        # (if they are the same file, they will naturally be deduplicated)
        for v, files_or_single in details.items():
            if v == version:
                continue
            if isinstance(files_or_single, (list, set, tuple)):
                # If the later version references the same file(s), include them
                for f in files_or_single:
                    if f in files:
                        files.add(f)
            else:
                if files_or_single in files:
                    files.add(files_or_single)

        result[logical_path] = files

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    # Handle the case where inventory is a dictionary.
    if isinstance(inventory, dict):
        for logical_path, value in inventory.items():
            files = set()

            # Case 1: value is a dict mapping version to a list of content files.
            if isinstance(value, dict):
                if version in value:
                    for cf in value[version]:
                        if isinstance(cf, (list, set)):
                            files.update(cf)
                        else:
                            files.add(cf)

            # Case 2: value is a list of entry dicts.
            elif isinstance(value, list):
                for entry in value:
                    if isinstance(entry, dict):
                        if entry.get("version") == version:
                            cf = entry.get("content_file")
                            if isinstance(cf, (list, set)):
                                files.update(cf)
                            else:
                                files.add(cf)

            if files:
                result[logical_path] = files

    # Handle the case where inventory is a list of entry dicts.
    elif isinstance(inventory, list):
        for entry in inventory:
            if isinstance(entry, dict):
                if entry.get("version") == version:
                    logical_path = entry.get("logical_path")
                    if logical_path is not None:
                        cf = entry.get("content_file")
                        if isinstance(cf, (list, set)):
                            result.setdefault(logical_path, set()).update(cf)
                        else:
                            result.setdefault(logical_path, set()).add(cf)

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in later versions than the version being described.
    """
    if isinstance(inventory, dict):
        iterable = inventory.values()
    else:
        iterable = inventory

    path_map = {}
    for item in iterable:
        # Support both dict items and objects with attributes
        logical_path = None
        ver = None
        content = None

        if isinstance(item, dict):
            logical_path = item.get('logical_path')
            ver = item.get('version')
            content = item.get('content_file')
        else:
            logical_path = getattr(item, 'logical_path', None)
            ver = getattr(item, 'version', None)
            content = getattr(item, 'content_file', None)

        if logical_path is None or ver is None or content is None:
            continue

        try:
            if str(ver) >= str(version):
                if logical_path not in path_map:
                    path_map[logical_path] = set()
                path_map[logical_path].add(content)
        except Exception:
            # If comparison fails, skip this entry
            continue

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, set, or tuple")

    manifest_set = set(manifest_files)

    for file_path, info in fixity.items():
        if file_path not in manifest_set:
            raise ValueError(f"Fixity contains unknown file: {file_path}")

        if not isinstance(info, dict):
            raise ValueError(f"Fixity entry for '{file_path}' must be a dictionary")

        if 'hash' not in info:
            raise ValueError(f"Missing 'hash' key in fixity entry for '{file_path}'")

        hash_val = info['hash']
        if not isinstance(hash_val, str) or not hash_val:
            raise ValueError(f"Invalid hash for '{file_path}': must be a non-empty string")

        # Optional size validation
        if 'size' in info:
            size_val = info['size']
            if not isinstance(size_val, int) or size_val < 0:
                raise ValueError(f"Invalid size for '{file_path}': must be a non-negative integer")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Missing 'files' key in fixity block")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")

    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dictionary")
        if 'path' not in entry or 'hash' not in entry:
            raise ValueError("Each file entry must contain 'path' and 'hash'")
        if not isinstance(entry['path'], str):
            raise ValueError("File path must be a string")
        if not isinstance(entry['hash'], str):
            raise ValueError("Hash must be a string")
        if entry['path'] not in manifest_files:
            raise ValueError(f"Fixity references unknown file: {entry['path']}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type check
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary, got %r" % type(fixity).__name__)

    # Expect a key that contains the individual file records; common names are
    # 'entries', 'items', or 'files'.  Accept any of these but enforce presence
    # of at least one of them.
    entry_keys = ('entries', 'items', 'files')
    for key in entry_keys:
        if key in fixity:
            entries = fixity[key]
            break
    else:
        raise ValueError("Fixity block must contain one of the keys: %s" % ', '.join(entry_keys))

    if not isinstance(entries, list):
        raise ValueError("The '%s' entry in the fixity block must be a list, got %r" % (key, type(entries).__name__))

    seen = set()
    for i, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise ValueError("Each entry in '%s' must be a dict, entry %d is %r" % (key, i, type(entry).__name__))

        required = {"file", "algorithm", "checksum"}
        missing = required - entry.keys()
        if missing:
            raise ValueError("Entry %d is missing required keys: %s" % (i, ', '.join(missing)))

        file_name = entry["file"]
        if file_name not in manifest_files:
            raise ValueError("Fixity entry %d references unknown file '%s'" % (i, file_name))

        # Optional: check duplicate file references
        if file_name in seen:
            raise ValueError("Duplicate fixity reference for file '%s' found in entry %d" % (file_name, i))
        seen.add(file_name)

        # Ensure algorithm is a non-empty string
        algo = entry["algorithm"]
        if not isinstance(algo, str) or not algo:
            raise ValueError("Entry %d has invalid algorithm value: %r" % (i, entry["algorithm"]))
        # Basic sanity check for common algorithms
        acceptable_algo = {"md5", "sha1", "sha256", "sha512"}
        if algo.lower() not in acceptable_algo:
            raise ValueError(
                "Entry %d uses unsupported algorithm '%s'. "
                "Acceptable values: %s" % (i, algo, ', '.join(sorted(acceptable_algo)))
            )

        # Verify checksum string is present and non-empty
        checksum = entry["checksum"]
        if not isinstance(checksum, str) or not checksum:
            raise ValueError("Entry %d has invalid checksum value: %r" % (i, checksum))

    # Ensure that all manifest files are referenced by at least one fixity entry
    missing_refs = set(manifest_files) - seen
    if missing_refs:
        raise ValueError("The following files from the manifest are not referenced in the fixity block: %s"
                         % ', '.join(sorted(missing_refs)))
    # Nothing else to return; validation passed.

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
    """
    # The block must be a mapping
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    # It must contain a 'files' key with a list
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")
    # Validate each entry
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry #{idx} is not a dict")
        # Each entry must specify a path
        if 'path' not in entry:
            raise ValueError(f"Fixity entry #{idx} missing required 'path'")
        path = entry['path']
        # The referenced path must exist in the provided manifest
        if path not in manifest_files:
            raise ValueError(f"Fixity entry #{idx} references unknown file: {path}")
        # Optional: verify checksum fields are present and strings
        for key in ('md5', 'sha1', 'sha256'):
            if key in entry:
                if not isinstance(entry[key], str):
                    raise ValueError(f"Fixity entry #{idx} '{key}' must be a string")
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be an iterable of file names")

    required_keys = {"type", "digest", "size"}

    for fname, entry in fixity.items():
        # Ensure file is in the manifest
        if fname not in manifest_files:
            raise ValueError(f"File '{fname}' referenced in fixity block is not present in the manifest")

        # Entry must be a dict with required keys
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry for file '{fname}' must be a dictionary")

        entry_keys = set(entry.keys())
        if entry_keys != required_keys:
            missing = required_keys - entry_keys
            extra = entry_keys - required_keys
            parts = []
            if missing:
                parts.append(f"missing keys: {', '.join(missing)}")
            if extra:
                parts.append(f"unexpected keys: {', '.join(extra)}")
            raise ValueError(f"Fixity entry for file '{fname}' has invalid structure: {'; '.join(parts)}")

        # Validate each field
        ftype = entry["type"]
        if not isinstance(ftype, str) or not ftype:
            raise ValueError(f"Invalid type for file '{fname}': must be a non-empty string")

        digest = entry["digest"]
        if not isinstance(digest, str) or not digest:
            raise ValueError(f"Invalid digest for file '{fname}': must be a non-empty string")

        size = entry["size"]
        if not (isinstance(size, int) and size >= 0):
            raise ValueError(f"Invalid size for file '{fname}': must be a non-negative integer")
    return True

def files_list(path):
