def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    data = {}
    for root, dirs, files in os.walk(folder):
        for fname in files:
            basename, ext = os.path.splitext(fname)
            full_path = os.path.join(root, fname)
            if ext.lower() == ".xml":
                # start a new group for this XML file
                data[basename] = {"xml": full_path}
            else:
                # add other files to the existing group, if any
                if basename in data:
                    data[basename].setdefault("files", []).append(full_path)
    return data

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    # First collect all XML files to use as keys
    packages = {}
    for entry in os.scandir(folder):
        if not entry.is_file():
            continue
        name, ext = os.path.splitext(entry.name)
        if ext.lower() == ".xml":
            packages[name] = {"xml": entry.path}
    # Now group all other files that share an XML basename
    for entry in os.scandir(folder):
        if not entry.is_file():
            continue
        name, ext = os.path.splitext(entry.name)
        if ext.lower() == ".xml":
            continue
        # Only include files that have a corresponding XML file
        if name in packages:
            key = ext.lower().lstrip(".")
            packages[name][key] = entry.path
    return packages

def add_rendition(self, lang, file_path):
    """Add a rendition for the given language.

    Maintains a mapping of original filenames to their renditions in
    different languages. Example::

        {
            "artigo02.pdf": {"en": "artigo02-en.pdf"},
        }
    """
    # Extract the original filename from the rendition
    base = os.path.basename(file_path)
    name, ext = os.path.splitext(base)
    # Remove a trailing "-lang" part if present
    if name.endswith(f'-{lang}'):
        original_name = name[:-(len(lang) + 1)] + ext
    else:
        # If no language suffix, assume the path is the original
        original_name = base

    # Store mapping on the instance
    if not hasattr(self, '_renditions'):
        self._renditions = {}
    rend_dict = self._renditions.setdefault(original_name, {})
    rend_dict[lang] = file_path
    return True

def add_asset(self, basename, file_path):
    """
    {
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Map supported file extensions to their corresponding full paths.
    asset_mapping = {}
    extensions = ['.tiff', '.jpg', '.png']
    for ext in extensions:
        filename = f"{basename}{ext}"
        full_path = os.path.join(file_path, filename)
        if os.path.exists(full_path):
            asset_mapping[filename] = full_path
    return asset_mapping

def add_asset(self, basename, file_path):
        """
        "{
            "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
            "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
            "artigo02-gf03.png": "/path/artigo02-gf03.png",
        }
        """
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"Source file does not exist: {file_path}")
        dest_dir = getattr(self, "_asset_path", None)
        if dest_dir is None:
            raise AttributeError("Missing _asset_path attribute on self.")
        if not os.path.isdir(dest_dir):
            os.makedirs(dest_dir, exist_ok=True)
        dest_path = os.path.join(dest_dir, basename)
        if os.path.exists(dest_path):
            os.remove(dest_path)
        shutil.copyfile(file_path, dest_path)
        return dest_path

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    with zipfile.ZipFile(zip_path, 'r') as zf:
        # Collect XML basenames (without directory)
        xml_basenames = set()
        for entry in zf.infolist():
            name = entry.filename
            if name.endswith('/') or name.endswith('.'):
                continue
            if name.endswith('.xml'):
                base, _ = os.path.splitext(name)
                xml_basenames.add(base)

        # Group all files that share these basenames
        for base in xml_basenames:
            group = {}
            for entry in zf.infolist():
                name = entry.filename
                if name.endswith('/') or name.endswith('.'):
                    continue
                entry_base, _ = os.path.splitext(name)
                if entry_base == base:
                    try:
                        content = zf.read(entry)
                        group[name] = content
                    except KeyError:
                        pass
            result[base] = group

    return result

