def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(obj, level):
        prefix = ' ' * (level * indent)
        # Handle dictionaries
        if isinstance(obj, dict):
            lines = [prefix + '{']
            for k, v in sorted(obj.items()):
                lines.append(prefix + '  ' + _format(k, 0) + ': ' + _format(v, level + 1).lstrip())
            lines.append(prefix + '}')
            return '\n'.join(lines)
        # Handle lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            if isinstance(obj, list):
                open_sym, close_sym = '[', ']'
            elif isinstance(obj, tuple):
                open_sym, close_sym = '(', ')'
            else:
                open_sym, close_sym = '{', '}'
            lines = [prefix + open_sym]
            for item in obj:
                lines.append(prefix + '  ' + _format(item, level + 1).lstrip())
            lines.append(prefix + close_sym)
            return '\n'.join(lines)
        # Handle simple types
        s = repr(obj)
        if debug:
            s += f' ({type(obj).__name__})'
        return prefix + s

    return _format(self, 0)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(obj, level):
        prefix = ' ' * (level * 2)
        if isinstance(obj, dict):
            lines = [prefix + '{']
            for key, value in obj.items():
                lines.append(_format(value, level + 1))
            lines.append(prefix + '}')
            return '\n'.join(lines)
        elif isinstance(obj, (list, tuple)):
            open_br = '[' if isinstance(obj, list) else '('
            close_br = ']' if isinstance(obj, list) else ')'
            lines = [prefix + open_br]
            for item in obj:
                lines.append(_format(item, level + 1))
            lines.append(prefix + close_br)
            return '\n'.join(lines)
        elif hasattr(obj, "__dict__"):
            if not debug:
                return _format(vars(obj), level)
            else:
                lines = [prefix + f"{obj.__class__.__name__}:"]
                for k, v in vars(obj).items():
                    lines.append(_format(v, level + 1))
                return '\n'.join(lines)
        else:
            return prefix + repr(obj)

    return _format(self, indent)

