    if style is None:
        style = 'full'
    valid_styles = {'full', 'compact', 'major', 'majorminor', 'tuple'}
    if style not in valid_styles:
        raise ValueError(f"Unknown style {style!r}")

    # Helper to convert a piece to a string, keeping None/empty intact.
    def _to_str(x):
        return '' if x in (None, '') else str(x)

    str_pieces = [_to_str(p) for p in pieces]

    if style == 'full':
        return '.'.join(str_pieces)
