        # Remove trailing zeros or empty components.
        while str_pieces and (str_pieces[-1] == '0' or str_pieces[-1] == ''):
            str_pieces.pop()
        return '.'.join(str_pieces)
    elif style == 'major':
        return str_pieces[0] if str_pieces else ''
    elif style == 'majorminor':
        return '.'.join(str_pieces[:2])
    elif style == 'tuple':
        # Return original pieces as a tuple (preserving types).
        return tuple(pieces)
    else:
        # Fallback – should never reach here due to validation above.
        return '.'.join(str_pieces)

