def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        warnings = []

        # Retrieve all objects in the hierarchy.  This method is expected to
        # be implemented by the concrete subclass.  If it is missing we fall
        # back to an empty list to avoid raising an error here.
        try:
            objects = self.get_all_objects()
        except Exception:
            objects = []

        for obj in objects:
            num_objects += 1
            valid = True

            if validate_objects:
                try:
                    obj.validate()
                except Exception as exc:
                    warnings.append(f"Validation error in {obj}: {exc}")
                    valid = False

            if check_digests and valid:
                try:
                    expected = obj.compute_digest()
                    if expected != getattr(obj, "digest", None):
                        warnings.append(f"Digest mismatch in {obj}")
                        valid = False
                except Exception as exc:
                    warnings.append(f"Digest check failed for {obj}: {exc}")
                    valid = False

            if valid:
                good_objects += 1

        if show_warnings:
            for w in warnings:
                print(w)

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _is_object(node):
        return (
            hasattr(node, "validate") and callable(node.validate)
            or hasattr(node, "is_valid")
            or isinstance(node, dict)
            and any(k in node for k in ("checksum", "data", "content", "value"))
        )

    def _process_obj(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        valid = True

        # Basic object validation
        if validate_objects:
            if hasattr(obj, "validate") and callable(obj.validate):
                try:
                    valid = bool(obj.validate())
                except Exception as exc:
                    valid = False
                    if show_warnings:
                        print(f"Validation error for {obj!r}: {exc}")
            elif hasattr(obj, "is_valid"):
                valid = bool(obj.is_valid)

        # Digest check
        if check_digests and valid:
            if hasattr(obj, "check_digest") and callable(obj.check_digest):
                try:
                    if not obj.check_digest():
                        valid = False
                        if show_warnings:
                            print(f"Digest mismatch for {obj!r}")
                except Exception as exc:
                    valid = False
                    if show_warnings:
                        print(f"Digest error for {obj!r}: {exc}")

        # Simple dict based digest check if no method exists
        if check_digests and valid and isinstance(obj, dict):
            # attempt a sha256 of the json-ish representation
            try:
                import hashlib, json
                json_text = json.dumps(obj, sort_keys=True).encode("utf-8")
                computed = hashlib.sha256(json_text).hexdigest()
                expected = obj.get("checksum") or obj.get("sha256")
                if expected and computed != expected:
                    valid = False
                    if show_warnings:
                        print(f"Digest mismatch for dict {obj!r}")
            except Exception:
                pass

        if valid:
            good_objects += 1

    def _visit(node):
        # If the node itself is an object, validate it
        if _is_object(node):
            _process_obj(node)

        # Recurse into possible children
        children_attrs = ("children", "child_nodes", "subnodes", "nodes", "elements")
        for attr in children_attrs:
            if hasattr(node, attr):
                try:
                    for child in getattr(node, attr):
                        _visit(child)
                except Exception:
                    continue
        if isinstance(node, dict):
            # Common patterns for children and embedded objects
            for key in ("objects", "entries", "nodes", "values"):
                if key in node:
                    for child in node[key]:
                        _visit(child)
            # Recursively visit any dict values that look like nodes
            for v in node.values():
                if isinstance(v, (dict, list)) and not _is_object(v):
                    _visit(v)

    # Determine the starting point of traversal
    start = getattr(self, "root", None)
    if start is None and hasattr(self, "get_root"):
        try:
            start = self.get_root()
        except Exception:
            pass

    if start is None:
        if show_warnings:
            print("No starting point for hierarchy traversal.")
        return 0, 0

    _visit(start)
    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json

    # Resolve the root path for the OCFL container.
    root_path = str(self.root_path)
    if os.path.exists(root_path):
        raise ValueError(f"OCFL root '{root_path}' already exists.")

    # Create the base root directory.
    try:
        os.makedirs(root_path, exist_ok=False)
    except OSError as exc:
        raise ValueError(f"Unable to create OCFL root at '{root_path}': {exc}") from exc

    # Create the OCFL meta directory structure.
    ocfl_dir = os.path.join(root_path, ".ocfl")
    obj_dir = os.path.join(ocfl_dir, "objects")
    try:
        os.makedirs(obj_dir, exist_ok=False)
    except OSError as exc:
        raise ValueError(f"Unable to create OCFL meta directories: {exc}") from exc

    # Initialize the root manifest with minimal required fields.
    manifest_path = os.path.join(ocfl_dir, "manifest.json")
    manifest_data = {
        "ocfl-version": "1.0",
        "objects": {}
    }
    try:
        with open(manifest_path, "w", encoding="utf-8") as fp:
            json.dump(manifest_data, fp, indent=2)
    except OSError as exc:
        raise ValueError(f"Failed to write manifest: {exc}") from exc

    # Store the path internally for future reference.
    self._root = root_path
    self._ocfl_dir = ocfl_dir
    self._obj_dir = obj_dir
