def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    if not hasattr(self, "root_inventory"):
        raise AttributeError("self.root_inventory must be set before calling validate_version_inventories")

    root_inv = self.root_inventory  # expected dict of path->digest

    # Store any digests that differ from the root inventory
    differing_digests = {}

    for vd in version_dirs:
        # Assume inventory file name is 'inventory.json' inside each version dir
        inv_path = os.path.join(vd, "inventory.json")
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory file in version directory '{vd}'")

        with open(inv_path, "r", encoding="utf-8") as f:
            try:
                inv_data = json.load(f)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Inventory in '{vd}' is not valid JSON: {exc}") from exc

        if not isinstance(inv_data, dict):
            raise ValueError(f"Inventory in '{vd}' must be a mapping of path to digest")

        # Each inventory MUST contain all items from the root inventory
        for path, root_digest in root_inv.items():
            if path not in inv_data:
                raise ValueError(
                    f"Inventory in '{vd}' is missing expected entry for path '{path}'"
                )
            # Record any digest that differs from the root
            if inv_data[path] != root_digest:
                differing_digests.setdefault(path, []).append(
                    {"version": vd, "digest": inv_data[path]}
                )

    # Store differences for later validation steps
    self.inventory_differences = differing_digests

    return differing_digests

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Load the root inventory once
    root_inventory = getattr(self, "_root_inventory", None)
    if root_inventory is None:
        try:
            root_inventory = self._load_inventory(self.root)
        except Exception as exc:
            raise RuntimeError(f"Failed to load root inventory: {exc}") from exc
        self._root_inventory = root_inventory

    # Dictionary to hold mismatches: {version: {file: (root_digest, ver_digest)}}
    self._inventory_mismatches = {}

    for ver in version_dirs:
        ver_dir = os.path.join(self.root, str(ver))
        inv_path = os.path.join(ver_dir, getattr(self, "inventory_file", "inventory.json"))

        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file '{inv_path}' for version {ver}")

        try:
            ver_inventory = self._load_inventory(ver_dir)
        except Exception as exc:
            raise RuntimeError(f"Failed to load inventory for version {ver}: {exc}") from exc

        mismatches = {}
        for filename, digest in ver_inventory.items():
            root_digest = root_inventory.get(filename)
            if root_digest != digest:
                mismatches[filename] = (root_digest, digest)

        if mismatches:
            self._inventory_mismatches[ver] = mismatches

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    inventories = {}
    for vd in version_dirs:
        inv_path = os.path.join(vd, "inventory.json")
        with open(inv_path, "r", encoding="utf-8") as f:
            inventories[vd] = json.load(f)

    root_inventory = inventories[version_dirs[-1]]
    mismatches = {}
    cumulative_keys = set()

    for vd in version_dirs:
        inv = inventories[vd]
        # Ensure the current inventory contains all keys seen so far.
        if not cumulative_keys.issubset(inv.keys()):
            missing = cumulative_keys - inv.keys()
            raise ValueError(
                f"Inventory {vd} is missing keys: {sorted(missing)}"
            )
        cumulative_keys = set(inv.keys())

        for key, digest in inv.items():
            root_digest = root_inventory.get(key)
            if root_digest is None:
                continue
            if digest != root_digest:
                mismatches[key] = (digest, root_digest)

    self.mismatched_digests = mismatches
    return self

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    if not os.path.exists(path):
        return f"not found: {path}"
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        # Check for object: a "0=*" file directly in this directory
        for f in os.listdir(path):
            if f.startswith('0='):
                return 'object'
        # Check for root: any immediate subdirectory that contains a "0=*" file
        for d in os.listdir(path):
            sub = os.path.join(path, d)
            if not os.path.isdir(sub):
                continue
            try:
                for f in os.listdir(sub):
                    if f.startswith('0='):
                        return 'root'
            except OSError:
                continue
        return f'unknown - contains no object identifiers in {path}'
    return f"unknown path type: {path}"

