def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples
    in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the
    result. If there are colliding keys with non-MappingNode values (e.g.,
    integers or strings), the last of the values wins.
    """
    def _merge_values(a, b):
        """Recursively merge two ruamel.yaml node values."""
        # Only merge when both are MappingNode instances; otherwise, last wins.
        try:
            MappingNode  # ensure the class exists in the runtime
        except NameError:
            return b  # no MappingNode available, just keep last
        if isinstance(a, MappingNode) and isinstance(b, MappingNode):
            # Build dicts keyed by unique identifier (tag, value) for scalars.
            def to_dict(mnode):
                return {(k.tag, k.value): (k, v) for k, v in mnode.value}
            dict_a = to_dict(a)
            dict_b = to_dict(b)
            merged_entries = []
            seen = set()
            # Preserve the order of keys from the first appearance.
            for key_id in list(dict_a.keys()) + list(dict_b.keys()):
                if key_id in seen:
                    continue
                seen.add(key_id)
                if key_id in dict_a and key_id in dict_b:
                    merged_val = _merge_values(dict_a[key_id][1], dict_b[key_id][1])
                    key_node = dict_a[key_id][0]
                    merged_entries.append((key_node, merged_val))
                elif key_id in dict_a:
                    merged_entries.append(dict_a[key_id])
                else:
                    merged_entries.append(dict_b[key_id])
            return MappingNode(tag=a.tag, value=merged_entries)
        # Non-mapping collision: the later value wins.
        return b

    # Main merging logic for the top-level list of tuples.
    merged_map = {}          # key_id -> merged value
    key_nodes = {}           # key_id -> original key node (first occurrence)
    for key_node, val_node in nodes:
        key_id = (key_node.tag, key_node.value)
        if key_id not in merged_map:
            merged_map[key_id] = val_node
            key_nodes[key_id] = key_node
        else:
            merged_map[key_id] = _merge_values(merged_map[key_id], val_node)

    # Preserve the original order of first occurrences.
    result = [(key_nodes[key_id], merged_map[key_id]) for key_id in key_nodes]
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(a_mapping, b_mapping):
        # both are MappingNode value lists
        a_vals = a_mapping.value if hasattr(a_mapping, 'value') else a_mapping
        b_vals = b_mapping.value if hasattr(b_mapping, 'value') else b_mapping
        merged = {}
        # Preserve order from first mapping
        for key_node, val_node in a_vals:
            merged[key_node.value] = (key_node, val_node)
        for key_node, val_node in b_vals:
            k = key_node.value
            if k in merged:
                old_val = merged[k][1]
                if is_mapping(old_val) and is_mapping(val_node):
                    merged_val = merge_mapping_nodes(old_val, val_node)
                else:
                    merged_val = val_node
                merged[k] = (key_node, merged_val)
            else:
                merged[k] = (key_node, val_node)
        return list(merged.values())

    def merge_nodes(a, b):
        if is_mapping(a) and is_mapping(b):
            return merge_mapping_nodes(a, b)
        return b  # last wins

    result_map = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in result_map:
            _, existing_val = result_map[key]
            merged_val = merge_nodes(existing_val, val_node)
            result_map[key] = (key_node, merged_val)
        else:
            result_map[key] = (key_node, val_node)
    return list(result_map.values())

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """

    def _merge_mapping_lists(list_a, list_b):
        """Merge two lists of (key_node, value_node) tuples representing a MappingNode."""
        merged_map = {}
        key_nodes = {}

        # Helper to get the string value used as a key
        def key_str(node):
            return getattr(node, "value", None)

        for k_node, v_node in list_a:
            ks = key_str(k_node)
            merged_map[ks] = v_node
            key_nodes[ks] = k_node

        for k_node, v_node in list_b:
            ks = key_str(k_node)
            if ks in merged_map:
                existing_val = merged_map[ks]
                # If both values are mapping nodes, merge deeply
                if (
                    hasattr(existing_val, "tag")
                    and "map" in getattr(existing_val, "tag", "")
                    and hasattr(v_node, "tag")
                    and "map" in getattr(v_node, "tag", "")
                ):
                    # Recursively merge mapping node values
                    merged_sub = _merge_mapping_lists(existing_val.value, v_node.value)
                    # Preserve the original mapping node's structure
                    existing_val.value = merged_sub
                else:
                    # Non-mapping values: last wins
                    merged_map[ks] = v_node
            else:
                merged_map[ks] = v_node
                key_nodes[ks] = k_node

        # Reconstruct the list of tuples in original key order
        return [(key_nodes[ks], merged_map[ks]) for ks in key_nodes]

    result_map = {}
    first_keys = {}

    def key_str(node):
        return getattr(node, "value", None)

    for key_node, val_node in nodes:
        ks = key_str(key_node)
        if ks in result_map:
            existing_val = result_map[ks]
            if (
                hasattr(existing_val, "tag")
                and "map" in getattr(existing_val, "tag", "")
                and hasattr(val_node, "tag")
                and "map" in getattr(val_node, "tag", "")
            ):
                # Merge mapping node values
                merged = _merge_mapping_lists(existing_val.value, val_node.value)
                existing_val.value = merged
            else:
                # Non-mapping values: last wins
                result_map[ks] = val_node
        else:
            result_map[ks] = val_node
            first_keys[ks] = key_node

    # Build final list preserving the original key order (first occurrence)
    return [(first_keys[ks], result_map[ks]) for ks in first_keys]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
