    for key_node, val_node in nodes:
        key = (key_node.tag, key_node.value)
        if key not in merged:
            merged[key] = (key_node, val_node)
            order.append(key)
        else:
            existing_key_node, existing_val_node = merged[key]
            if isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                new_val = merge_mappings(existing_val_node, val_node)
                merged[key] = (existing_key_node, new_val)
            else:
                # Replace with the new value (last wins)
                merged[key] = (existing_key_node, val_node)

    return [merged[key] for key in order]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def merge_mapping_nodes(old_node, new_node):
        """Recursively merge two MappingNodes."""
        old_items = old_node.value
        new_items = new_node.value
        old_keys = {k_node.value for k_node, _ in old_items}

        # Build a dict to track merged items keyed by string key
        merged_dict = {}
        for k_node, v_node in old_items:
            merged_dict[k_node.value] = (k_node, v_node)

        for k_node, v_node in new_items:
            key = k_node.value
            if key in merged_dict:
                old_k_node, old_v_node = merged_dict[key]
                if isinstance(old_v_node, ruamel.yaml.nodes.MappingNode) and isinstance(v_node, ruamel.yaml.nodes.MappingNode):
                    # Recursively merge nested mappings
                    merged_v_node = merge_mapping_nodes(old_v_node, v_node)
                    merged_dict[key] = (old_k_node, merged_v_node)
                else:
                    # New value wins, keep original key node
                    merged_dict[key] = (old_k_node, v_node)
            else:
                merged_dict[key] = (k_node, v_node)

        # Preserve ordering: old items first, then new keys that weren't present
        result_list = []
        for old_k_node, _ in old_items:
            key = old_k_node.value
            result_list.append(merged_dict[key])
        for new_k_node, _ in new_items:
            key = new_k_node.value
            if key not in old_keys:
                result_list.append(merged_dict[key])

        return ruamel.yaml.nodes.MappingNode(old_node.tag, result_list)

    merged = {}
    order = []

    for key_node, val_node in nodes:
        key_str = key_node.value
        if key_str in merged:
            old_key_node, old_val_node = merged[key_str]
            if isinstance(old_val_node, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = merge_mapping_nodes(old_val_node, val_node)
                merged[key_str] = (old_key_node, merged_val)
            else:
                # Replace with new value, keep original key node
                merged[key_str] = (old_key_node, val_node)
        else:
            merged[key_str] = (key_node, val_node)
            order.append(key_str)

    return [(merged[k][0], merged[k][1]) for k in order]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping(node):
        """Return True if node is a MappingNode based on common attributes."""
        return hasattr(node, 'tag') and isinstance(getattr(node, 'tag', ''), str) and node.tag.endswith(':map')

    def merge_node_values(a, b):
        """Merge two node values."""
        if is_mapping(a) and is_mapping(b):
            # Deep merge the mapping entries
            merged_entries = deep_merge_nodes(a.value + b.value)
            # Return new mapping node with same tag as b (or a if b is None)
            cls = b.__class__ if hasattr(b, '__class__') else a.__class__
            return cls(tag=b.tag if hasattr(b, 'tag') else a.tag, value=merged_entries)
        # If one is not a mapping, the later value wins
        return b

    # Keep insertion order of first occurrence
    result_dict = {}
    first_key_nodes = {}

    for key_node, val_node in nodes:
        if not hasattr(key_node, 'value'):
            continue  # skip malformed entries
        key = key_node.value
        if key in result_dict:
            result_dict[key] = merge_node_values(result_dict[key], val_node)
        else:
            result_dict[key] = val_node
            first_key_nodes[key] = key_node

    # Build result list preserving original key-node ordering
    merged_list = []
    for key in first_key_nodes:
        merged_list.append((first_key_nodes[key], result_dict[key]))
    return merged_list

