def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    for key, value in url_args.items():
        placeholder = "{" + str(key) + "}"
        if placeholder in url:
            try:
                # Percent-encode the value to keep URL valid
                encoded_value = urllib.parse.quote(str(value), safe='')
            except Exception:
                encoded_value = str(value)
            url = url.replace(placeholder, encoded_value)

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''
    if not isinstance(url_args, Mapping):
        raise TypeError('url_args must be a mapping')

    # Replace {key} placeholders
    def _curly_replacer(match):
        key = match.group(1)
        return str(url_args[key]) if key in url_args else match.group(0)

    url = re.sub(r'\{([^}]+)\}', _curly_replacer, url)

    # Replace :key style placeholders (common in path params)
    def _colon_replacer(match):
        key = match.group(1)
        return str(url_args[key]) if key in url_args else match.group(0)

    url = re.sub(r':([^/?#]+)', _colon_replacer, url)

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''
    # Replace placeholders like {key} with the corresponding value from url_args.
    # If a key is missing, leave the placeholder unchanged.
    def repl(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))
    pattern = r'\{(\w+)\}'
    return re.sub(pattern, repl, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            return urllib.parse.quote_plus(str(url_args[key]))
        return match.group(0)

    # Replace placeholders of the form {key}
    url = re.sub(r'\{([a-zA-Z0-9_]+)\}', _repl, url)

    # Also replace placeholders of the form :key (common in REST APIs)
    def _colon_repl(match):
        key = match.group(1)
        if key in url_args:
            return urllib.parse.quote_plus(str(url_args[key]))
        return match.group(0)

    url = re.sub(r':([a-zA-Z0-9_]+)', _colon_repl, url)

    return url

