def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
            n //= base
        result = ''.join(reversed(digits))
    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non-negative")
        result = result.rjust(padding, alphabet[0])
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        digits = [alphabet[0]]
    else:
        base = len(alphabet)
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits = digits[::-1]
    if padding is not None and padding > len(digits):
        digits = [alphabet[0]] * (padding - len(digits)) + digits
    return ''.join(digits)

def int_to_string(number: int, alphabet: list, padding: int | None = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        s = alphabet[0]
    else:
        base = len(alphabet)
        digits = []
        abs_number = number
        negative = abs_number < 0
        if negative:
            abs_number = -abs_number
        while abs_number:
            abs_number, rem = divmod(abs_number, base)
            digits.append(alphabet[rem])
        s = ''.join(reversed(digits))
        if negative:
            s = '-' + s

    if padding is not None:
        pad_len = padding - len(s)
        if pad_len > 0:
            s = alphabet[0] * pad_len + s

    return s

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    def _replace(d):
        for key, value in list(d.items()):
            if key == register_value:
                d[register_number] = d.pop(key)
            if isinstance(value, dict):
                _replace(value)
            elif isinstance(value, (list, tuple)):
                for item in value:
                    if isinstance(item, dict):
                        _replace(item)
    _replace(flow_params)
    return flow_params

