def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = {cls}
    while queue:
        c = queue.pop()
        seen.add(c)
        subcs = c.__subclasses__()
        for subc in subcs:
            if subc not in seen:
                queue.add(subc)
    seen.discard(cls)
    return seen

