    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    base = len(alphabet)
    inv = {ch: i for i, ch in enumerate(alphabet)}
    n = 0
    for ch in string:
        if ch not in inv:
            raise ValueError(f"Character {ch!r} not in alphabet")
        n = n * base + inv[ch]
    return n

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}
    value = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character {ch!r} not in the provided alphabet")
        value = value * base + char_to_value[ch]
    return value

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("alphabet must contain at least one character")
    mapping = {ch: i for i, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character {ch!r} not found in alphabet")
        result = result * base + mapping[ch]
    return result

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    def wild_to_regex(key):
        # Convert wildcard '*' to regex '.*' and escape other characters
        return ''.join('.*' if ch == '*' else re.escape(ch) for ch in key)

    return {wild_to_regex(k): v for k, v in item.items()}

