def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os, shlex
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1
    if platform == 1:
        return shlex.split(s, posix=True)
    if platform == 0:
        return shlex.split(s, posix=False)
    raise ValueError(f'Unsupported platform spec: {platform}')

def split(s, platform='this'):
    import re, sys, shlex
    # Determine whether to use POSIX or Windows splitting rules
    if platform == 'this':
        is_posix = not sys.platform.startswith('win')
    else:
        is_posix = bool(platform)
    if is_posix:
        # Regular expression for POSIX-like command line splitting.
        # Matches either:
        #   * a quoted string that may contain escaped quotes or backslashes
        #   * a run of non-whitespace characters
        pattern = re.compile(r'''(?:"((?:[^"\\]|\\.)*)"|(\S+))''', re.VERBOSE)
        args = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                # Quoted part: unescape \" and \\ according to POSIX rules
                token = m.group(1)
                token = token.replace(r'\"', '"').replace(r'\\', '\\')
            else:
                token = m.group(2)
            args.append(token)
        return args
    else:
        # Windows/CMD style splitting. Use shlex with posix=False which emulates
        # the usual Windows command-line parsing rules.
        return shlex.split(s, posix=False)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.
    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
    """
    import sys
    # Determine platform
    if platform == 'this':
        is_win = sys.platform.startswith('win')
    elif platform == 1:
        is_win = False
    elif platform == 0:
        is_win = True
    else:
        raise ValueError('Unsupported platform: %r' % platform)

    if not is_win:
        # POSIX-style splitting (similar to shlex.split)
        token_re = re.compile(
            r'''(?:
                "([^"\\]*(?:\\.[^"\\]*)*)"   |   # double-quoted
                '([^'\\]*(?:\\.[^'\\]*)*)'   |   # single-quoted
                ([^\s"']+)                     # bare word
            )''', re.VERBOSE)
        tokens = []
        for m in token_re.finditer(s):
            dq, sq, bare = m.groups()
            if dq is not None:
                tok = dq
            elif sq is not None:
                tok = sq
            else:
                tok = bare
            # Replace escaped characters
            tok = re.sub(r'\\(.)', r'\1', tok)
            tokens.append(tok)
        return tokens
    else:
        # Windows/CMD-style splitting
        tokens = []
        buf = []
        in_quotes = False
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch in (' ', '\t'):
                if not in_quotes:
                    if buf:
                        tokens.append(''.join(buf))
                        buf = []
                    i += 1
                    continue
            if ch == '"':
                # Count preceding backslashes
                backslashes = 0
                j = i - 1
                while j >= 0 and s[j] == '\\':
                    backslashes += 1
                    j -= 1
                if backslashes % 2 == 0:
                    # Toggle quoting
                    in_quotes = not in_quotes
                else:
                    # Escaped quote
                    buf.append('"')
                i += 1
                continue
            if ch == '\\':
                # Count consecutive backslashes
                backslashes = 1
                i += 1
                while i < n and s[i] == '\\':
                    backslashes += 1
                    i += 1
                if i < n and s[i] == '"':
                    # Backslashes before a quote
                    buf.extend(['\\'] * (backslashes // 2))
                    if backslashes % 2 == 1:
                        buf.append('"')
                        i += 1
                    else:
                        # Unescaped quote
                        in_quotes = not in_quotes
                        i += 1
                else:
                    buf.extend(['\\'] * backslashes)
                continue
            buf.append(ch)
            i += 1
        if buf:
            tokens.append(''.join(buf))
        return tokens

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    from pathlib import Path
    import os

    # Determine the name for the extracted repository directory
    if filename is None:
        name = Path(archive_path).name
        # Strip common archive extensions
        for ext in ('.tar.gz', '.tgz', '.tar.bz2', '.tbz2',
                    '.tar.xz', '.txz', '.tar', '.gz', '.bz2', '.xz', '.zip'):
            if name.lower().endswith(ext):
                name = name[: -len(ext)]
                break
        else:
            # Fallback to stem (removes last suffix)
            name = Path(archive_path).stem
    else:
        name = filename

    dest_dir = Path(tmp_path) / name
    dest_dir.mkdir(parents=True, exist_ok=False)

    # Extract the archive using appropriate command
    if archive_path.lower().endswith(('.tar.gz', '.tgz')):
        subprocess.check_call(['tar', '-xzf', archive_path, '-C', str(dest_dir)])
    elif archive_path.lower().endswith(('.tar.bz2', '.tbz2')):
        subprocess.check_call(['tar', '-xjf', archive_path, '-C', str(dest_dir)])
    elif archive_path.lower().endswith(('.tar.xz', '.txz')):
        subprocess.check_call(['tar', '-xJf', archive_path, '-C', str(dest_dir)])
    elif archive_path.lower().endswith('.zip'):
        subprocess.check_call(['unzip', '-q', archive_path, '-d', str(dest_dir)])
    else:
        # Default to tar extraction (works for .tar and unknown extensions)
        subprocess.check_call(['tar', '-xf', archive_path, '-C', str(dest_dir)])

    return f'file://{dest_dir.resolve()}')

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
