def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == 'always'):
        return None

    if not isinstance(frequency, str):
        raise ValueError('Frequency must be a string')

    parts = frequency.strip().lower().split()
    if len(parts) != 2:
        raise ValueError('Frequency string must contain exactly a number and a unit')

    amount_str, unit = parts
    try:
        amount = int(amount_str)
    except ValueError:
        raise ValueError(f'Invalid numeric value in frequency: {amount_str}')

    unit_map = {
        'days': 'days', 'day': 'days',
        'hours': 'hours', 'hour': 'hours',
        'minutes': 'minutes', 'minute': 'minutes',
        'min': 'minutes', 'mins': 'minutes',
        'seconds': 'seconds', 'second': 'seconds',
        'sec': 'seconds', 'secs': 'seconds',
        'weeks': 'weeks', 'week': 'weeks',
        'months': 'days', 'month': 'days',
        'years': 'days', 'year': 'days',
    }

    if unit not in unit_map:
        raise ValueError(f'Unknown time unit: {unit}')

    kw = {}
    if unit in ('months', 'year'):
        # Approximate months as 30 days, years as 365 days
        multiplier = 30 if unit == 'months' else 365
        kw['days'] = amount * multiplier
    else:
        kw[unit_map[unit]] = amount

    try:
        return datetime.timedelta(**kw)
    except TypeError as exc:
        raise ValueError(f'Failed to create timedelta: {exc}') from exc

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == "always"):
        return None
    if not isinstance(frequency, str):
        raise ValueError("frequency must be a string")
    parts = frequency.strip().split()
    if len(parts) != 2:
        raise ValueError(f"cannot parse frequency '{frequency}'")
    value_part, unit_part = parts
    try:
        value = int(value_part)
    except ValueError:
        raise ValueError(f"invalid numeric value '{value_part}' in frequency '{frequency}'")
    unit = unit_part.lower()
    if unit in ("days", "day", "d"):
        return datetime.timedelta(days=value)
    if unit in ("weeks", "week", "w"):
        return datetime.timedelta(weeks=value)
    if unit in ("hours", "hour", "h"):
        return datetime.timedelta(hours=value)
    if unit in ("minutes", "minute", "m"):
        return datetime.timedelta(minutes=value)
    if unit in ("seconds", "second", "s"):
        return datetime.timedelta(seconds=value)
    raise ValueError(f"unknown time unit '{unit}' in frequency '{frequency}'")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick checks for common localhost representations
    common_local = {
        'localhost',
        '127.0.0.1',
        '::1',
        'localhost.localdomain',
        'localhost6',
        'ip6-localhost',
    }
    if host in common_local:
        return True
    try:
        # Resolve the host and inspect all returned addresses
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            ip = sockaddr[0]
            if family == socket.AF_INET:
                # Any 127.x.x.x address is considered loopback for IPv4
                if ip == '127.0.0.1' or ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                # ::1 is the only standard loopback for IPv6
                if ip == '::1':
                    return True
    except socket.gaierror:
        # Host could not be resolved; not localhost
        pass
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve the host to its IP addresses
        addr_info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Hostname could not be resolved
        return False

    for entry in addr_info:
        family, socktype, proto, canonname, sockaddr = entry
        ip = sockaddr[0]

        # Handle IPv4 loopback network (127.0.0.0/8)
        if family == socket.AF_INET:
            try:
                # IPv4 addresses are dotted-decimal
                if ip.split('.')[0] == '127':
                    return True
            except Exception:
                pass

        # Handle IPv6 loopback address
        elif family == socket.AF_INET6:
            if ip == '::1':
                return True

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve the host to one or more address info entries
        addr_infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in addr_infos:
        ip = sockaddr[0]
        # IPv4 loopback
        if family == socket.AF_INET and ip.startswith("127."):
            return True
        # IPv6 loopback
        if family == socket.AF_INET6 and ip == "::1":
            return True

    # Fallback: compare against the local machine's own name
    try:
        local_name = socket.gethostname()
        if local_name == host:
            return True
    except Exception:
        pass

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Handle the literal hostname 'localhost'
    if str(host).lower() == "localhost":
        return True

    try:
        # Convert host to address information
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # If we can't resolve, assume not local
        return False

    for family, _, _, _, sockaddr in addrinfo:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == "127.0.0.1":
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip in ("::1", "0:0:0:0:0:0:0:1"):
                return True

    return False

