def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract the variable name and possible default from the matcher
    name = None
    default = None

    # 1. Matchers that provide a group dictionary (e.g., re.Match)
    if hasattr(matcher, "groupdict"):
        gd = matcher.groupdict()
        if "name" in gd:
            name = gd["name"]
        elif "" in gd:          # some regexes use unnamed groups
            name = gd[""]
        # the default may be in the 'default' group, or may be the second value in defaults dict
        default = gd.get("default")

    # 2. Matchers that are tuples or lists (name, default?)
    if name is None and isinstance(matcher, (tuple, list)):
        if len(matcher) >= 1:
            name = matcher[0]
        if len(matcher) >= 2:
            default = matcher[1]

    # 3. Generic object with attributes
    if name is None:
        if hasattr(matcher, "name"):
            name = getattr(matcher, "name")
        if hasattr(matcher, "default"):
            default = getattr(matcher, "default")

    if name is None:
        raise ValueError("Matcher must contain a variable name")

    # Retrieve from environment
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default
    raise EnvironmentError(f"environment variable '{name}' not found")

