def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd = [commands] + list(args)
    else:
        cmd = list(commands) + list(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")
        if cwd:
            print(f"  Working directory: {cwd}")
        if env:
            print(f"  Environment vars: {env}")

    # Prepare stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    # Execute the command
    result = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr_target,
        text=True
    )

    # If verbose, display output
    if verbose:
        if result.stdout:
            print(f"stdout:\n{result.stdout}")
        if not hide_stderr and result.stderr:
            print(f"stderr:\n{result.stderr}")

    # Raise an error if the command failed
    if result.returncode != 0:
        err_msg = f"Command {' '.join(cmd)} failed with return code {result.returncode}"
        if result.stderr and not hide_stderr:
            err_msg += f"\nError output: {result.stderr}"
        raise subprocess.CalledProcessError(result.returncode, cmd, output=result.stdout, stderr=result.stderr)

    return result

