def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    def _merge_dicts(target, override):
        for key, value in override.items():
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                _merge_dicts(target[key], value)
            else:
                target[key] = value
        return target

    def _resolve_env(cfg):
        import os
        if isinstance(cfg, dict):
            return {k: _resolve_env(v) for k, v in cfg.items()}
        elif isinstance(cfg, list):
            return [_resolve_env(v) for v in cfg]
        elif isinstance(cfg, str):
            # replace ${VAR} patterns
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, cfg)
        else:
            return cfg

    configs = {}
    error_records = []
    for fn in config_filenames:
        try:
            with open(fn, 'r') as f:
                raw = f.read()
            if fn.endswith('.toml'):
                import toml
                cfg = toml.loads(raw)
            elif fn.endswith(('.yaml', '.yml')):
                import yaml
                cfg = yaml.safe_load(raw)
            elif fn.endswith('.json'):
                import json
                cfg = json.loads(raw)
            else:
                raise ValueError(f'Unsupported config file extension: {fn}')
            if not isinstance(cfg, dict):
                raise TypeError(f'Config in {fn} is not a dictionary')
            if resolve_env:
                cfg = _resolve_env(cfg)
            if overrides:
                cfg = _merge_dicts(cfg, overrides)
            configs[fn] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fn,
                lineno=0,
                msg=f'Error parsing {fn}: {e}',
                args=(),
                exc_info=None
            )
            record.exc_info = (type(e), e, e.__traceback__)
            error_records.append(record)
    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    import configparser
    import sys
    from collections.abc import Mapping

    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    parsed_configs = {}
    error_records = []

    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, Mapping):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        return value

    def _parse_file(filepath):
        _, ext = os.path.splitext(filepath.lower())
        with open(filepath, 'r', encoding='utf-8') as f:
            raw = f.read()
        if ext in ('.yaml', '.yml'):
            if yaml is None:
                raise ValueError('yaml module not available')
            return yaml.safe_load(raw)
        if ext == '.json':
            return json.loads(raw)
        if ext == '.toml':
            if toml is None:
                raise ValueError('toml module not available')
            return toml.loads(raw)
        if ext in ('.ini', '.cfg'):
            parser = configparser.ConfigParser()
            parser.read_string(raw)
            return {section: dict(parser.items(section)) for section in parser.sections()}
        # fallback: try yaml then json
        try:
            if yaml is not None:
                return yaml.safe_load(raw)
        except Exception:
            pass
        try:
            return json.loads(raw)
        except Exception:
            pass
        raise ValueError('Unable to determine file format for {}'.format(filepath))

    for fname in config_filenames:
        try:
            conf = _parse_file(fname)
            if not isinstance(conf, Mapping):
                raise ValueError('Parsed configuration is not a mapping')
            if resolve_env:
                conf = _expand_env(conf)
            if overrides:
                # shallow merge: override top-level keys
                conf.update(overrides)
            parsed_configs[fname] = conf
        except Exception as e:
            exc_info = sys.exc_info()
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Error parsing configuration file {fname}: {e}',
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)

    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    parsed_configs = {}
    error_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            msg = f"Configuration file {filename} does not exist."
            rec = logging.LogRecord(name=filename, level=logging.ERROR, pathname=filename,
                                    lineno=0, msg=msg, args=(), exc_info=None)
            error_records.append(rec)
            continue
        try:
            with open(filename, 'r') as f:
                content = f.read()
            if filename.endswith('.toml'):
                config = toml.loads(content)
            elif filename.endswith(('.yaml', '.yml')):
                config = yaml.safe_load(content)
            elif filename.endswith('.json'):
                config = json.loads(content)
            else:
                config = yaml.safe_load(content)
            if config is None:
                config = {}
        except Exception as e:
            msg = f"Error parsing {filename}: {e}"
            rec = logging.LogRecord(name=filename, level=logging.ERROR, pathname=filename,
                                    lineno=0, msg=msg, args=(), exc_info=None)
            error_records.append(rec)
            continue

        if overrides:
            for key, val in overrides.items():
                parts = key.split('.')
                d = config
                for part in parts[:-1]:
                    if part not in d or not isinstance(d[part], dict):
                        d[part] = {}
                    d = d[part]
                d[parts[-1]] = val

        if resolve_env:
            def _resolve(obj):
                if isinstance(obj, dict):
                    return {k: _resolve(v) for k, v in obj.items()}
                elif isinstance(obj, list):
                    return [_resolve(item) for item in obj]
                elif isinstance(obj, str):
                    return os.path.expandvars(obj)
                else:
                    return obj
            config = _resolve(config)

        parsed_configs[filename] = config

    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml
    import configparser
    cfgs = {}
    error_records = []

    def _resolve_env(value):
        '''Recursively resolve environment variables in strings.'''
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env(v) for v in value]
        return value

    for fname in config_filenames:
        try:
            _, ext = os.path.splitext(fname.lower())
            if ext in ['.json']:
                with open(fname, 'r', encoding='utf-8') as fd:
                    cfg = json.load(fd)
            elif ext in ['.yaml', '.yml']:
                with open(fname, 'r', encoding='utf-8') as fd:
                    cfg = yaml.safe_load(fd)
            elif ext in ['.toml']:
                with open(fname, 'r', encoding='utf-8') as fd:
                    cfg = toml.loads(fd.read())
            elif ext in ['.ini']:
                cp = configparser.ConfigParser()
                cp.read(fname)
                # convert to dict
                cfg = {s: dict(cp.items(s)) for s in cp.sections()}
            else:
                raise ValueError(f'Unsupported file extension: {ext}')

            if cfg is None or not isinstance(cfg, dict):
                raise ValueError('Parsed configuration is not a dict')

            if resolve_env:
                cfg = _resolve_env(cfg)

            if overrides:
                # apply overrides (shallow)
                for key, val in overrides.items():
                    cfg[key] = val

            cfgs[fname] = cfg

        except Exception as exc:
            # create a LogRecord for the error
            exc_msg = f'Error loading {fname}: {exc}'
            rec = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=exc_msg,
                args=None,
                exc_info=exc
            )
            error_records.append(rec)

    return cfgs, error_records

