        handlers = {}
        for name, obj in cls.__dict__.items():
            if isinstance(obj, type):
                # Look for common attribute names for protocol version.
                ver = getattr(obj, "protocol_version", None)
                if ver is None:
                    ver = getattr(obj, "PROTOCOL_VERSION", None)
                if isinstance(ver, tuple) and len(ver) == 2:
                    handlers[ver] = obj

        # If a specific protocol version is requested, filter the result.
        if protocol_version is not None:
            # Ensure the user supplied a tuple describing the protocol.
            if not (isinstance(protocol_version, tuple) and len(protocol_version) == 2):
                raise TypeError(
