                    f"got {protocol_version!r}"
                )
            # Return the matching handler, if any, in a new dictionary
            # (or an empty dictionary if unsupported).
            return (
                {protocol_version: handlers[protocol_version]}
                if protocol_version in handlers
                else {}
            )

        # No specific version requested: return all discovered handlers.
        return handlers

