def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Convert each raw value into a Bookmark instance.
    # We assume a Bookmark class with a from_raw_value classmethod exists.
    if values is None:
        return cls([])
    try:
        bookmarks = [Bookmark.from_raw_value(v) for v in values]
    except Exception:
        # Fallback: keep raw values if conversion fails
        bookmarks = list(values)
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Immediate mapping for common built‑in sequence types
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # Handle file‑like objects: read the contents
    if hasattr(seq, "read"):
        data = seq.read(bufsize) if bufsize is not None else seq.read()
        return data, type(data)

    # Handle any other iterable: consume it into a list
    if hasattr(seq, "__iter__"):
        seq_list = list(seq)
        return seq_list, type(seq_list)

    raise TypeError("Cannot derive a sequence from %r" % (seq,))

