    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a standard sequence type, return it unchanged
    if isinstance(seq, (str, bytes, list, tuple)):
        return seq, type(seq)
    # If seq is a file-like object, read it (optionally using a buffer size)
    if hasattr(seq, 'read'):
        if bufsize is not None:
            data = seq.read(bufsize)
        else:
            data = seq.read()
        return data, 'file'
    # If seq is an iterable but not one of the above, convert to a list
    if hasattr(seq, '__iter__'):
        data = list(seq)
