def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a string or bytes, return it unchanged
    if isinstance(seq, (str, bytes)):
        return (seq, type(seq).__name__)

    # If seq is a list or tuple, return it unchanged
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq).__name__)

    # If the object has a 'seq' attribute (e.g., a SequenceRecord), use it
    if hasattr(seq, "seq"):
        return (seq.seq, type(seq).__name__)

    # Handle generic iterables
    if hasattr(seq, "__iter__"):
        # If a buffer size is supplied, use itertools.islice to limit elements
        if bufsize is not None:
            from itertools import islice
            items = list(islice(seq, bufsize))
        else:
            items = list(seq)

        # Try to collapse to a string if it is a sequence of single-character strings
        try:
            if all(isinstance(x, str) and len(x) == 1 for x in items):
                return ("".join(items), type(seq).__name__)
        except Exception:
            pass

        return (items, type(seq).__name__)

    # Fallback: represent seq as a string
    return (str(seq), type(seq).__name__)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type (list or tuple), return it as is
    if isinstance(seq, (list, tuple)):
        return seq, 'sequence'
    # If seq is a string or bytes, return a list of its items
    if isinstance(seq, (str, bytes)):
        return list(seq), 'string'
    # If seq has a read method (file‑like object), read its contents
    if hasattr(seq, 'read'):
        if bufsize is None:
            data = seq.read()
        else:
            parts = []
            while True:
                chunk = seq.read(bufsize)
                if not chunk:
                    break
                parts.append(chunk)
            data = "".join(parts)
        return data, 'file'
    # Fallback: try to coerce to a list
    try:
        return list(seq), 'iterable'
    except Exception:
        return None, 'unknown'

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Check interface provision (if not tentative)
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append(
                f"candidate does not provide interface {iface!r}"
            )

    # 2. Gather potential methods and attributes from the interface
    try:
        interface_members = iface.__dict__
    except AttributeError:
        interface_members = {}

    # Distinguish methods and attributes
    import inspect

    interface_methods = {
        name: obj
        for name, obj in interface_members.items()
        if callable(obj) and not name.startswith("__")
    }
    interface_attrs = {
        name: val
        for name, val in interface_members.items()
        if not callable(val) and not name.startswith("__")
    }

    # 3. Validate methods
    for name, iface_method in interface_methods.items():
        candidate_attr = getattr(candidate, name, None)
        if candidate_attr is None:
            errors.append(f"candidate missing method '{name}'")
            continue
        if not callable(candidate_attr):
            errors.append(f"candidate attribute '{name}' is not callable")
            continue
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(candidate_attr)
        except Exception:
            # If signature inspection fails, skip detailed comparison
            continue
        # Compare parameter names and count, ignoring 'self' if present
        iface_params = [
            p for p in iface_sig.parameters.values()
            if p.name != "self"
        ]
        cand_params = [
            p for p in cand_sig.parameters.values()
            if p.name != "self"
        ]
        if len(iface_params) != len(cand_params) or \
           [p.name for p in iface_params] != [p.name for p in cand_params]:
            errors.append(
                f"signature mismatch for method '{name}': "
                f"expected {iface_sig}, got {cand_sig}"
            )

    # 4. Validate attributes
    for name in interface_attrs:
        if not hasattr(candidate, name):
            errors.append(f"candidate missing attribute '{name}'")

    # 5. Raise or return
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            msg = "Multiple interface errors: " + "; ".join(errors)
            raise zope.interface.Invalid(msg)
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Ensure iface is a class or type
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")
    # Determine the class of the candidate
    impl_cls = candidate if isinstance(candidate, type) else candidate.__class__
    # Collect abstract methods or required attributes from iface
    abstract_attrs = getattr(iface, "__abstractmethods__", set())
    # If not using ABC, fall back to public methods
    if not abstract_attrs:
        abstract_attrs = set(
            name for name, obj in vars(iface).items()
            if callable(obj) and not name.startswith("_")
        )
    missing = [attr for attr in abstract_attrs if not hasattr(impl_cls, attr)]
    if missing:
        if tentative:
            return False
        raise TypeError(
            f"{impl_cls.__name__} does not implement required attributes {missing}"
        )
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Resolve the class of the candidate if it is not a class itself
    cand_cls = candidate if isinstance(candidate, type) else getattr(candidate, "__class__", None)
    if cand_cls is None:
        if tentative:
            return False
        raise TypeError(f"candidate {candidate!r} does not have an associated class")

    # If both are classes and candidate inherits from iface, we accept
    if isinstance(iface, type) and isinstance(cand_cls, type) and issubclass(cand_cls, iface):
        return True

    # Explicitly check that all non-magic attributes defined on iface are present on candidate
    for name in dir(iface):
        if name.startswith("_") or name == "mro":
            continue
        # Skip attributes that are defined in type and are not part of the interface contract
        if getattr(iface, name, None) is getattr(type, name, None):
            continue
        # Ensure the candidate has this attribute
        if not hasattr(cand_cls, name):
            if tentative:
                return False
            raise AttributeError(
                f"Candidate class {cand_cls.__name__!r} does not provide required attribute {name!r} from interface {iface.__name__!r}"
            )
        # If the attribute is a callable on the interface, require the candidate to provide a callable as well
        iface_attr = getattr(iface, name)
        cand_attr = getattr(cand_cls, name)
        if callable(iface_attr) and not callable(cand_attr):
            if tentative:
                return False
            raise TypeError(
                f"Attribute {name!r} of candidate class {cand_cls.__name__!r} should be callable to satisfy interface {iface.__name__!r}"
            )
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    The function checks that the candidate implements all required
    attributes and methods defined on the interface.  If ``tentative``
    is ``True`` the check is more permissive – it will simply skip
    optional interface members (those whose name starts with ``query_``).
    The function returns ``True`` when the candidate passes the
    verification, otherwise it returns ``False``.
    """
    # Determine the candidate class (handle instance or class inputs)
    cand_cls = candidate if isinstance(candidate, type) else candidate.__class__

    # Gather interface attributes that are not private or optional
    required_attrs = [
        name for name in dir(iface)
        if not name.startswith('_') and not name.startswith('query_')
    ]

    for attr_name in required_attrs:
        iface_attr = getattr(iface, attr_name, None)
        # If the interface doesn't actually define the attribute, skip
        if iface_attr is None:
            continue

        # For callable interface members, ensure the candidate provides a
        # callable attribute with the same name
        if callable(iface_attr):
            if not hasattr(cand_cls, attr_name):
                if tentative:
                    # Skip the check on tentative verification
                    continue
                return False
            candidate_attr = getattr(cand_cls, attr_name)
            if not callable(candidate_attr):
                return False
        else:
            # For data attributes, simply check presence
            if not hasattr(cand_cls, attr_name):
                if tentative:
                    continue
                return False

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is given, use it
    if explicit_mc is not None:
        return explicit_mc

    # No bases: default to the built‑in type
    if not bases:
        return type

    # Gather the metaclasses of all base classes
    mcs = set(type(b) for b in bases)

    # Single metaclass case – just return it
    if len(mcs) == 1:
        return mcs.pop()

    # Find a candidate that is a subclass of all other metaclasses
    for candidate in mcs:
        if all(issubclass(candidate, other) or candidate == other for other in mcs):
            return candidate

    # If no such metaclass exists, raise an error
    raise TypeError("metaclass conflict: no common metaclass found")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is provided, it takes precedence
    if explicit_mc is not None:
        return explicit_mc

    # No bases: default to type
    if not bases:
        return type

    # Helper to resolve metaclass conflict between two candidates
    def _pick_single(mcs1, mcs2):
        if mcs1 is mcs2:
            return mcs1
        if issubclass(mcs1, mcs2):
            return mcs1
        if issubclass(mcs2, mcs1):
            return mcs2
        raise TypeError(f"metaclass conflict: {mcs1} and {mcs2}")

    # Use the metaclass of the first base as the initial candidate
    mcs = type(bases[0])

    # Resolve against the remaining bases
    for base in bases[1:]:
        mcs = _pick_single(mcs, type(base))

    return mcs

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    if not bases:
        return type
    mcs = [type(b) for b in bases]
    common = mcs[0]
    for mc in mcs[1:]:
        if issubclass(common, mc):
            continue
        if issubclass(mc, common):
            common = mc
            continue
        raise TypeError(f"metaclass conflict: {common} is not a subclass of {mc}")
    return common

