def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {}
    # Try JSON format first
    try:
        data = json.loads(document)
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel")
            href = link.get("href") or link.get("template")
            if rel and href:
                if rel == "hcard":
                    result["hcard_url"] = href
                else:
                    result[rel] = href
        result["subject"] = data.get("subject")
        result["aliases"] = data.get("aliases", [])
        return result
    except Exception:
        pass

    # Fallback to XRD (XML) format
    try:
        root = ET.fromstring(document)
    except Exception:
        return result

    for elem in root.iter():
        tag = elem.tag.lower()
        if tag.endswith("link"):
            rel = elem.attrib.get("rel")
            href = elem.attrib.get("href") or elem.attrib.get("template")
            if rel and href:
                if rel == "hcard":
                    result["hcard_url"] = href
                else:
                    result[rel] = href
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree

    # Try to parse as JSON first – the “new” format
    try:
        data = json.loads(document)
        # The JSON webfinger typically contains a `links` array
        if isinstance(data, dict) and "links" in data:
            result: Dict[str, str] = {}
            for link in data["links"]:
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    result[rel] = href
            # Preserve subject if present
            result["subject"] = data.get("subject")
            return result
        # If it is already a dict, return it as‑is
        if isinstance(data, dict):
            return data
    except Exception:
        # Not JSON – fall back to XRD (XML) parsing
        pass

    # XRD format – the “old” format
    try:
        root = ElementTree.fromstring(document)
    except ElementTree.ParseError:
        # Not XML either, return empty dict
        return {}

    result: Dict[str, str] = {}
    # Namespace used by Diaspora for XRD
    ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
    # Collect all link tags with their rel/href attributes
    for link in root.findall("xrd:Link", ns):
        rel = link.get("rel")
        href = link.get("href")
        if rel and href:
            result[rel] = href
    # Subject element
    subject = root.find("xrd:Subject", ns)
    if subject is not None and subject.text:
        result["subject"] = subject.text
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
