    return result

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).
    The function returns a dictionary containing at least the keys:
    - subject (acct URI)
    - aliases (list of local account or web URLs)
    - links (dict mapping rel to href)
    - hcard_url (href for hcard rel)
    - self_url (href for self rel)

    If parsing fails, None is returned.
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt JSON parsing
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        data = None

    if data is None:
        # Try XML (XRD) parsing
        try:
            tree = ET.fromstring(document)
        except ET.ParseError:
            return None

        def _local_name(tag: str) -> str:
            return tag.split("}", 1)[-1] if "}" in tag else tag

        subject = None
        aliases = []
        links = {}

        for elem in tree.iter():
            tag = _local_name(elem.tag)
            if tag == "Subject" and elem.text:
                subject = elem.text.strip()
            elif tag == "Alias" and elem.text:
                aliases.append(elem.text.strip())
            elif tag == "Link":
                rel = elem.get("rel")
                if not rel:
                    continue
                # URI can be in a child element
                uri_elem = None
                # Try namespaced URI
                for child in elem:
                    if _local_name(child.tag) == "URI" and child.text:
                        uri_elem = child
                        break
                if uri_elem is None and elem.find("URI") is not None:
                    uri_elem = elem.find("URI")
                if uri_elem is not None and uri_elem.text:
                    links[rel] = uri_elem.text.strip()

        data = {
            "subject": subject,
            "aliases": aliases,
            "links": links,
        }

    # Normalize JSON data
    if isinstance(data, dict):
        # If JSON format
        if "links" in data and isinstance(data["links"], list):
            links_dict = {}
            for link in data["links"]:
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    links_dict[rel] = href
            data["links"] = links_dict
        else:
            # Ensure links is a dict
            data["links"] = data.get("links", {})
        data["hcard_url"] = data["links"].get("hcard")
        data["self_url"] = data["links"].get("self")
    return data

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        return json.loads(document)
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except Exception:
        # Invalid format – return an empty dict
        return {}

    result: Dict[str, str] = {}
    for elem in root.iter():
        # The Link elements may have namespace prefixes
        tag = elem.tag.lower()
        if tag.endswith('link'):
            rel = elem.attrib.get('rel', '')
            href = elem.attrib.get('href')
            template = elem.attrib.get('template')

            # Map common relations to expected dictionary keys
            if rel == 'hcard':
                key = 'hcard_url'
                result[key] = href or template
            elif rel == 'photo':
                key = 'photo_url'
                result[key] = href or template
            elif rel == 'self':
                key = 'self_url'
                result[key] = href or template
            elif rel == 'lrdd':
                key = 'lrdd_template'
                result[key] = href or template
            else:
                # Generic fallback: use the rel value as the key
                key = rel.replace(' ', '_')
                result[key] = href or template
    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split('@')[1]
    except Exception:
        return None

    # Construct the WebFinger URL using HTTPS first
    url = 'https://{}/.well-known/webfinger?resource=acct:{}'.format(host, quote(handle))

    try:
        with urllib2.urlopen(url) as response:
            if response.getcode() == 200:
                return response.read()
    except Exception:
        # Fallback to HTTP if HTTPS fails
        url = 'http://{}/.well-known/webfinger?resource=acct:{}'.format(host, quote(handle))
        try:
            with urllib2.urlopen(url) as response:
                if response.getcode() == 200:
                    return response.read()
        except Exception:
            return None

    return None

