def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Extract host from the handle (expected format: user@host or acct:user@host)
        if handle.startswith("acct:"):
            handle = handle[5:]
        host = handle.split("@", 1)[1]
    except (AttributeError, IndexError):
        # Invalid handle format
        return None
    try:
        from urllib.parse import quote
        from urllib.request import urlopen
        from urllib.error import URLError, HTTPError

        webfinger_path = f"/.well-known/webfinger?resource=acct:{quote(handle)}"
        url = f"https://{host}{webfinger_path}"
        with urlopen(url) as response:
            content = response.read()
            if isinstance(content, bytes):
                return content.decode("utf-8", errors="replace")
            return content
    except (URLError, HTTPError, ValueError):
        # Network / HTTP error or malformed response
        return None
    except Exception:
        # Catch any unexpected errors and suppress them
        return None

