def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Ensure we have a list of directories to search
        dirs = settings_dirs if isinstance(settings_dirs, (list, tuple)) else [settings_dirs]
        matched_files = []

        for directory in dirs:
            if not os.path.isdir(directory):
                # Skip if the path is not a directory
                continue
            for entry in os.listdir(directory):
                # Skip hidden files
                if entry.startswith('.'):
                    continue

                # If spec_option is a frozenset, tuple, or list of extensions, filter accordingly
                if isinstance(spec_option, (frozenset, tuple, list)):
                    if not any(entry.endswith(ext) for ext in spec_option):
                        continue
                # If spec_option is a callable, use it as a filter predicate
                elif callable(spec_option):
                    if not spec_option(entry):
                        continue
                # If spec_option is a string, assume it is an ending
                elif isinstance(spec_option, str):
                    if not entry.endswith(spec_option):
                        continue

                # Build the absolute path and add it to the result
                matched_files.append(os.path.join(directory, entry))

        # Return the files sorted for deterministic ordering
        return sorted(matched_files)
    except Exception:
        # If anything goes wrong, return an empty list rather than propagating the error
        return []

