def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(d):
        if not isinstance(d, dict):
            return d
        result = {}
        for key, value in d.items():
            if key == 'include':
                # 'include' must contain either a list or a dict
                includes = value if isinstance(value, (list, tuple)) else [value]
                for inc in includes:
                    if isinstance(inc, dict):
                        # Merge the included dict into the result
                        inc_resolved = _resolve(inc)
                        result.update(inc_resolved)
                # Do not carry the 'include' key itself
                continue
            # Recursively resolve nested structures
            result[key] = _resolve(value)
        return result
    return _resolve(parser_dict)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _merge_into(target, source):
        for key, val in source.items():
            if (
                key in target
                and isinstance(target[key], dict)
                and isinstance(val, dict)
            ):
                _merge_into(target[key], val)
            else:
                target[key] = val

    if not isinstance(parser_dict, dict):
        return parser_dict

    # Resolve top-level include if present
    include = parser_dict.pop("include", None)
    if include is not None:
        if isinstance(include, dict):
            _merge_into(parser_dict, include)
        elif isinstance(include, list):
            for inc in include:
                if isinstance(inc, dict):
                    _merge_into(parser_dict, inc)

    # Recursively process nested dicts
    for key, val in list(parser_dict.items()):
        if isinstance(val, dict):
            parser_dict[key] = self._include_groups(val)

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    includes = parser_dict.pop('include', None)
    if not includes:
        return
    for name, inc_val in includes.items():
        if name in parser_dict:
            cur_val = parser_dict[name]
            if isinstance(cur_val, dict) and isinstance(inc_val, dict):
                # merge dictionaries: inc_val overrides cur_val
                cur_val.update(inc_val)
                parser_dict[name] = cur_val
            else:
                parser_dict[name] = inc_val
        else:
            parser_dict[name] = inc_val

