    """Resolve arguments' values from spec and other sources.

    This method builds a dictionary of argument values by first looking up
    each argument's value in ``self.spec``.  If the spec does not provide a
    value it falls back to the default defined on the argument.  For
    arguments representing dictionaries (``DictOption``) the method
    recursively gathers defaults from the nested scheme.

    Returns:
        dict: Mapping of argument names to resolved values.
    """
    defaults = {}
    for arg in self.args:
        # Skip non-option objects that may appear in the argument list.
        if not isinstance(arg, _BaseOpt):
            continue

        # Try to fetch a value from the spec; fall back to the argument's own
        # default if necessary.  ``self.spec`` may be any mapping- or
        # attribute-like object; if it does not provide ``get`` we ignore it.
        try:
            spec_val = getattr(self.spec, "get", lambda k, d=None: None)(arg.name, None)
        except Exception:
            spec_val = None

        # If the spec supplied a value, use it; otherwise use the default.
        if spec_val is not None:
            defaults[arg.name] = spec_val
        elif not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # Handle nested dictionary options.
        if isinstance(arg, DictOption):
            scheme = getattr(arg, "scheme", None)
            if scheme:
                nested = scheme.get_spec_defaults()
                if nested:
                    defaults[arg.name] = nested

    return defaults

