def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Default deprecation mapping can be overridden by subclass
    deprecations = getattr(self, 'deprecations', {})
    if not isinstance(deprecations, dict):
        return

    # Helper to issue a warning for deprecated keys
    def _warn_old(name, old_val, location):
        new_name = deprecations.get(name)
        if new_name:
            warnings.warn(
                f"Keyword argument '{name}' used in {location} is deprecated "
                f"in favour of '{new_name}'. It will be removed in a future "
                f"version.",
                category=DeprecationWarning,
                stacklevel=2,
            )

    # Check CLI arguments for deprecated keys
    for key, val in cli_args.items():
        if key in deprecations:
            _warn_old(key, val, 'CLI')

    # Check answer-file arguments for deprecated keys
    for key, val in answer_file_args.items():
        if key in deprecations:
            _warn_old(key, val, 'answer file')

    # Detect conflicts where both CLI and answer file specify the same deprecated key
    for key in deprecations:
        if key in cli_args and key in answer_file_args:
            warnings.warn(
                f"Deprecated argument '{key}' specified in both CLI and answer file; "
                "CLI value will take precedence.",
                category=DeprecationWarning,
                stacklevel=2,
            )

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not hasattr(self, "_commands"):
        raise AttributeError("Parser options have not been initialized (missing _commands)")
    try:
        command = self._commands[command_name]
    except KeyError as exc:
        raise KeyError(f"Unknown command name: {command_name}") from exc
    # The command entry is expected to have an 'options' key holding a list.
    options = command.get("options")
    if options is None:
        raise ValueError(f"Command '{command_name}' does not define an 'options' list")
    if not isinstance(options, list):
        raise TypeError(f"Command '{command_name}' options should be a list, got {type(options).__name__}")
    return options

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not command_name:
        return []

    # Try to locate the command definition in common attribute names.
    commands = getattr(self, "_commands", {})
    cmd = commands.get(command_name)

    if cmd is None:
        commands = getattr(self, "commands", {})
        cmd = commands.get(command_name)

    if cmd is None:
        return []

    # The command object may expose its options in several ways.
    # Support dicts with an 'options' key, objects with 'options' or 'specs'
    # attributes, and fallback to an empty list if not found.
    if isinstance(cmd, dict):
        return cmd.get("options", [])
    if hasattr(cmd, "options"):
        return getattr(cmd, "options")
    if hasattr(cmd, "specs"):
        return getattr(cmd, "specs")
    return []

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # If a dictionary of command parsers is available
    if hasattr(self, "commands") and isinstance(self.commands, dict):
        cmd_obj = self.commands.get(command_name)
        if cmd_obj is None:
            raise ValueError(f"Unknown command: {command_name!r}")
        # Assume each command parser has an 'options' attribute or can expose
        # the parsed namespace which contains all defined attributes.
        if hasattr(cmd_obj, "options"):
            return cmd_obj.options
        if hasattr(cmd_obj, "add_argument"):
            # No direct list, so we return an empty placeholder
            return []
    # Fallback to a direct mapping of command names to option lists
    if hasattr(self, "options") and isinstance(self.options, dict):
        return self.options.get(command_name, [])
    # Try a method that might provide the options
    method_name = f"get_{command_name}_options"
    if hasattr(self, method_name) and callable(getattr(self, method_name)):
        return getattr(self, method_name)()
    # Last resort: if an attribute with the command name holds the options
    if hasattr(self, command_name):
        attr = getattr(self, command_name)
        if isinstance(attr, list):
            return attr
        if hasattr(attr, "options"):
            return attr.options
    raise ValueError(f"Could not find options for command {command_name!r}")

