    if spec is None:
        raise KeyError(
            f"Option spec for command '{command_name}' and argument '{argument_name}' not found"
        )
    return spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        return self._spec[command_name][argument_name]
    except KeyError:
        return None

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Fetch the command specifications mapping from the instance
    cmd_specs = getattr(self, 'commands', None)
    if cmd_specs is None:
        raise AttributeError("The instance does not have a 'commands' attribute.")
    # Retrieve the spec dictionary for the requested command
    command_spec = cmd_specs.get(command_name)
    if command_spec is None:
        # Command not found; return None to indicate absence
        return None
    # The command spec may be a mapping of option names to their specs
    # Return the spec for the requested argument if present
    if isinstance(command_spec, dict):
        return command_spec.get(argument_name)
    # If the command spec is not a dict, we cannot extract an individual option;
    # return the entire spec as the fallback
    return command_spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
