def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = set()

    # If args is a mapping (e.g., argparse Namespace converted to dict)
    if isinstance(args, dict):
        for key in args:
            if key.startswith('_') or key.startswith('no_'):
                silent.add(key)

    # If args is an argparse Namespace or similar with __dict__
    else:
        try:
            for key in vars(args):
                if key.startswith('_') or key.startswith('no_'):
                    silent.add(key)
        except Exception:
            # Fallback: iterate over sequence of strings
            if hasattr(args, '__iter__'):
                for item in args:
                    if isinstance(item, str) and (item.startswith('-no-') or item.startswith('--no-')):
                        # keep the argument as passed (with dashes)
                        silent.add(item.lstrip('-'))
    return sorted(silent)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required_args', None)
    if required is None:
        # If no explicit list, assume all keys in args are required
        return
    for name in required:
        if name not in args or args[name] is None:
            raise InvalidArgumentError(f"Missing required argument: {name}")

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # If the class defines an explicit list of required arguments, use it;
    # otherwise assume any argument with a None value is missing.
    required_keys = getattr(self, 'required_args', None)
    if required_keys is None:
        # Implicit: treat None values as missing required arguments.
        missing = [name for name, value in args.items() if value is None]
    else:
        missing = [name for name in required_keys if name not in args or args[name] is None]

    if missing:
        raise ValueError(
            "Missing required argument%s: %s" %
            ('s' if len(missing) > 1 else '', ', '.join(missing))
        )
    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for key in getattr(self, 'required', ()):
        if key not in args or args[key] is None:
            raise InvalidArgumentError(f'{key} must be specified.')

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    if not isinstance(args, dict):
        raise TypeError('args must be a dictionary')
    required = getattr(self, 'required_args', [])
    missing = [k for k in required if k not in args]
    if missing:
        raise InvalidArgumentError('Missing required arguments: {}'.format(', '.join(missing)))

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_names = []

    for opt in options_spec:
        # Try to extract option name and required_when
        if isinstance(opt, dict):
            name = opt.get('name') or opt.get('arg') or opt.get('key')
            required_when = opt.get('required_when')
        else:
            # fallback to attributes
            name = getattr(opt, 'name', None) or getattr(opt, 'arg', None)
            required_when = getattr(opt, 'required_when', None)

        if not name or not required_when:
            continue

        # Evaluate a callable required_when
        if callable(required_when):
            try:
                match = required_when(command_name, args)
            except TypeError:
                try:
                    match = required_when(args)
                except Exception:
                    match = False
            if match:
                required_names.append(name)
            continue

        # Dictionary or mapping condition
        if isinstance(required_when, dict):
            match = True
            for k, v in required_when.items():
                if args.get(k) != v:
                    match = False
                    break
            if match:
                required_names.append(name)
            continue

        # List or tuple of conditions
        if isinstance(required_when, (list, tuple)):
            match = True
            for cond in required_when:
                if callable(cond):
                    try:
                        cond_match = cond(command_name, args)
                    except TypeError:
                        cond_match = cond(args)
                elif isinstance(cond, dict):
                    cond_match = all(args.get(k) == v for k, v in cond.items())
                else:
                    cond_match = False
                if not cond_match:
                    match = False
                    break
            if match:
                required_names.append(name)
            continue

        # If required_when is any other truthy value, treat as always required
        if required_when:
            required_names.append(name)

    return required_names

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec: the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_names = []

    for opt in options_spec:
        # Determine the argument name; fall back to keys that might hold it
        name = opt.get('name')
        if not name:
            name = opt.get('arg') or opt.get('dest')
        if not name:
            continue

        if not opt.get('required_when'):
            # No conditional requirement
            continue

        conditions = opt['required_when']
        # Normalize to a list of conditions
        if not isinstance(conditions, (list, tuple)):
            conditions = [conditions]

        matched = False
        for cond in conditions:
            # Condition may be a callable that receives args dict
            if callable(cond):
                try:
                    if cond(args):
                        matched = True
                        break
                except Exception:
                    continue
                continue

            # Condition may be a string: name of an argument that must be truthy
            if isinstance(cond, str):
                if cond in args and args[cond]:
                    matched = True
                    break
                continue

            # Condition may be a mapping
            if isinstance(cond, dict):
                # Optionally match command name
                if 'command' in cond and cond['command'] != command_name:
                    continue
                submatch = True
                for key, value in cond.items():
                    if key == 'command':
                        continue
                    # Equality check for values; for truthiness, use bool()
                    if args.get(key) != value:
                        submatch = False
                        break
                if submatch:
                    matched = True
                    break
                continue

            # Condition may be a list/tuple of pairs (name, value)
            if isinstance(cond, (list, tuple)):
                submatch = True
                for pair in cond:
                    if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                        submatch = False
                        break
                    key, value = pair
                    if args.get(key) != value:
                        submatch = False
                        break
                if submatch:
                    matched = True
                    break
                continue

        if matched:
            required_names.append(name)

    return required_names

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        conditional_args = []
        for opt in options_spec:
            # Determine option name (support dict or object with attributes)
            if isinstance(opt, dict):
                name = opt.get('name') or opt.get('dest')
                cond = opt.get('required_when')
            else:
                name = getattr(opt, 'name', None) or getattr(opt, 'dest', None)
                cond = getattr(opt, 'required_when', None)

            if not name or not cond:
                continue

            try:
                if callable(cond):
                    cond_met = bool(cond(args))
                else:
                    # Use args as local namespace for eval
                    cond_met = bool(eval(cond, {}, args))
            except Exception:
                cond_met = False

            if cond_met:
                conditional_args.append(name)

        return conditional_args

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        cond = opt.get('required_when')
        if cond is None:
            continue
        name = opt.get('name')
        if not name:
            continue

        take = False
        # Evaluate condition depending on its type
        if callable(cond):
            try:
                take = bool(cond(args))
            except Exception:
                take = False
        elif isinstance(cond, (list, tuple, set)):
            # All listed option names must be present and truthy
            take = all(args.get(item) for item in cond)
        elif isinstance(cond, dict):
            # All key-value pairs must match
            take = all(args.get(k) == v for k, v in cond.items())
        else:
            # Treat as boolean flag or literal truthy value
            take = bool(cond)

        if take:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_attrs in args.items():
        # Get the maximum allowed length, if any
        max_len = arg_attrs.get("max_length")
        if max_len is None:
            continue

        # Ensure the max_len is a non‑negative integer
        if not isinstance(max_len, int):
            raise TypeError(
                f"max_length for argument '{arg_name}' must be an int, got {type(max_len).__name__}"
            )
        if max_len < 0:
            raise ValueError(
                f"max_length for argument '{arg_name}' must be non‑negative, got {max_len}"
            )

        # Retrieve the argument value to validate
        value = arg_attrs.get("value")
        if value is None:
            continue

        # Only strings, containers and sequences can be measured for length
        try:
            value_len = len(value)
        except Exception:
            continue

        if value_len > max_len:
            raise ValueError(
                f"Length of argument '{arg_name}' ({value_len}) exceeds "
                f"maximum allowed ({max_len})."
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the argument specifications (might be a dict or a list).
    arg_specs = self.parsed_yaml.get('args', {})
    # Helper to get max length from spec (support both 'len' and 'length').
    def spec_max_len(spec):
        if not isinstance(spec, dict):
            return None
        return spec.get('len') if 'len' in spec else spec.get('length')

    # Process depending on spec structure.
    if isinstance(arg_specs, dict):
        for arg_name, attr_spec in arg_specs.items():
            max_len = spec_max_len(attr_spec)
            if max_len is None:
                continue
            if arg_name not in args:
                continue
            value = args[arg_name]
            if value is None:
                continue
            try:
                value_len = len(value)
            except Exception:
                continue
            if value_len > max_len:
                abort(
                    f"Argument '{arg_name}' length "
                    f"{value_len} exceeds maximum of {max_len}"
                )
    elif isinstance(arg_specs, list):
        for item in arg_specs:
            if not isinstance(item, dict):
                continue
            for arg_name, attr_spec in item.items():
                max_len = spec_max_len(attr_spec)
                if max_len is None:
                    continue
                if arg_name not in args:
                    continue
                value = args[arg_name]
                if value is None:
                    continue
                try:
                    value_len = len(value)
                except Exception:
                    continue
                if value_len > max_len:
                    abort(
                        f"Argument '{arg_name}' length "
                        f"{value_len} exceeds maximum of {max_len}"
                    )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Accept args as either a dict or a list of single-item dicts.
    if isinstance(args, dict):
        items = args.items()
    else:
        items = []
        for argdict in args:
            if isinstance(argdict, dict) and len(argdict) == 1:
                argname, argattrs = next(iter(argdict.items()))
                items.append((argname, argattrs))
            else:
                continue

    for argname, argattrs in items:
        if not isinstance(argattrs, dict):
            continue
        value = argattrs.get('value')
        max_len = argattrs.get('max_len') or argattrs.get('maxlength')
        # If there is no length constraint or no value, skip.
        if max_len is None or value is None:
            continue
        try:
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{argname}' exceeds maximum length of {max_len}: {value}"
                )
        except TypeError:
            # If the value has no length, ignore or raise depending on policy
            # Here we simply skip non-sizeable values.
            continue

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # `self.choices` is expected to be a mapping from argument name to
    # an iterable of allowed values.
    if not hasattr(self, 'choices') or not self.choices:
        return

    for name, value in args.items():
        if value is None:
            continue  # skip unset optional arguments
        if name in self.choices:
            valid = self.choices[name]
            if value not in valid:
                valid_list = list(valid)
                msg = (
                    f"Invalid value for '{name}': {value!r}. "
                    f"Must be one of: {valid_list}"
                )
                raise ValueError(msg)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Assume self.choices is a dict mapping argument names to an iterable of valid choices.
    for arg_name, arg_value in args.items():
        if arg_name in getattr(self, "choices", {}):
            valid_choices = self.choices[arg_name]
            if arg_value not in valid_choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {arg_value!r}. "
                    f"Expected one of {valid_choices!r}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to their allowed choices.
    # The class may store these in an attribute called `_choices`.
    choice_map = getattr(self, "_choices", {})
    for arg_name, arg_value in args.items():
        allowed = choice_map.get(arg_name)
        if not allowed:
            # No choices defined for this argument; skip validation.
            continue
        # Accept a scalar value or an iterable of values.
        if isinstance(arg_value, (list, tuple)):
            for val in arg_value:
                if val not in allowed:
                    raise ValueError(
                        f"Argument '{arg_name}' has an invalid choice: {val!r}. "
                        f"Allowed choices: {allowed!r}"
                    )
        else:
            if arg_value not in allowed:
                raise ValueError(
                    f"Argument '{arg_name}' has an invalid choice: {arg_value!r}. "
                    f"Allowed choices: {allowed!r}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Get the argument definitions from the parsed yaml
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        # locate the definition for this argument
        if isinstance(arg_defs, dict):
            prop = arg_defs.get(arg_name)
        elif isinstance(arg_defs, list):
            prop = None
            for item in arg_defs:
                if isinstance(item, dict) and arg_name in item:
                    prop = item[arg_name]
                    break
        else:
            prop = None

        # if no definition or no choices specified, skip validation
        if not prop or not isinstance(prop, dict):
            continue

        choices = prop.get('choices')
        if not choices:
            continue

        if isinstance(value, (list, tuple)):
            # If the command accepts a list of values, check each one
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {v}. "
                        f"Expected one of: {choices}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Expected one of: {choices}"
                )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of arguments to their allowed choices
    choices = getattr(self, 'choices', {})
    if not isinstance(choices, dict):
        # No choices mapping defined; nothing to validate
        return
    for arg_name, arg_value in args.items():
        if arg_name in choices:
            allowed = choices[arg_name]
            # Normalise allowed to an iterable if needed
            if not hasattr(allowed, "__iter__") or isinstance(allowed, (str, bytes)):
                allowed = (allowed,)
            if arg_value not in allowed:
                raise ValueError(
                    "Invalid value for argument `{}`: {}. Allowed values are: {}".format(
                        arg_name, arg_value, allowed
                    )
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments, which can be either a
                 three-element tuple/list ``(value, min_, max_)``, a
                 dictionary with keys ``'value'``, ``'min'`` and
                 ``'max'``, or an iterable of such items.

    :return: The original argument(s) if all values are within the
             specified ranges.
    :raise ValueError: If any value is outside its range.
    :raise TypeError: If the argument format is not recognized.
    """
    def _check_single(item):
        if isinstance(item, (list, tuple)) and len(item) == 3:
            value, min_, max_ = item
        elif isinstance(item, dict):
            if not {'value', 'min', 'max'}.issubset(item):
                raise TypeError("Dictionary must contain 'value', 'min', and 'max'")
            value = item['value']
            min_ = item['min']
            max_ = item['max']
        else:
            raise TypeError("Item must be a 3-element sequence or a dict with 'value', 'min', 'max'")
        if min_ is not None and value < min_:
            raise ValueError(f"Value {value} is less than minimum {min_}")
        if max_ is not None and value > max_:
            raise ValueError(f"Value {value} is greater than maximum {max_}")
        return item

    if isinstance(args, (list, tuple)):
        if len(args) == 3 and not isinstance(args[0], (list, tuple, dict)):
            # Single item
            return _check_single(args)
        else:
            # Iterable of items
            return [_check_single(item) for item in args]
    elif isinstance(args, dict):
        return _check_single(args)
    else:
        raise TypeError("Arguments must be a dict, a 3-element list/tuple, or an iterable of such items.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine the minimum and maximum allowed values from the instance
    min_val = getattr(self, 'min_', None)
    max_val = getattr(self, 'max_', None)

    if min_val is None or max_val is None:
        raise AttributeError("`min_` and `max_` must be defined on the instance")

    # Ensure `args` is iterable; if a single value is passed, wrap it
    if isinstance(args, (list, tuple)):
        iterable = args
    else:
        iterable = (args,)

    for index, value in enumerate(iterable):
        try:
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument at position {index} ({value}) is outside the allowed range "
                    f"[{min_val}, {max_val}]"
                )
        except TypeError:
            raise TypeError(
                f"Argument at position {index} ({value}) is not comparable to the "
                f"minimum ({min_val}) and maximum ({max_val}) values"
            )
    return iterable

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    if "value" not in args:
        raise KeyError("args dictionary must contain a 'value' key")

    value = args["value"]
    min_val = args.get("minimum", args.get("min"))
    max_val = args.get("maximum", args.get("max"))

    # If both bounds are missing, nothing to validate
    if min_val is None and max_val is None:
        return True

    if min_val is None:
        if value > max_val:
            raise ValueError(f"value {value} exceeds maximum {max_val}")
    elif max_val is None:
        if value < min_val:
            raise ValueError(f"value {value} is less than minimum {min_val}")
    else:
        if not (min_val <= value <= max_val):
            raise ValueError(f"value {value} not in range {min_val}..{max_val}")

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values."""
    # Ensure that this object defines the min and max attributes
    if not hasattr(self, "min_value") or not hasattr(self, "max_value"):
        raise AttributeError("Object must define 'min_value' and 'max_value' attributes")
    min_val = self.min_value
    max_val = self.max_value

    # Normalise args to an iterable of values
    if isinstance(args, dict):
        values = args.values()
    else:
        values = args

    for value in values:
        if value is None:
            continue
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"argument {value!r} not in range [{min_val}, {max_val}]")
        except TypeError as exc:
            raise TypeError(
                f"Cannot compare value {value!r} with range [{min_val}, {max_val}]") from exc

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    def _complex_type(value):
        # Apply conversion if specified
        convert = spec_option.get('convert')
        if convert:
            try:
                value = convert(value)
            except Exception as exc:
                raise ValueError(f"Error converting value for {option_name}: {exc}") from exc

        # Validate against allowed choices if provided
        if 'choices' in spec_option:
            choices = spec_option['choices']
            if value not in choices:
                raise ValueError(f"Invalid value for {option_name}. Expected one of {choices}")

        # Additional user-provided validators can be invoked here
        validate = spec_option.get('validate')
        if validate is not None:
            try:
                validate(value)
            except Exception as exc:
                raise ValueError(f"Validation failed for {option_name}: {exc}") from exc

        return value

    # Attach metadata for readability
    _complex_type.__name__ = f"{subcommand}_{type_name}_{option_name}"
    _complex_type.__qualname__ = f"{subcommand}.{type_name}.{option_name}"

    # Store the created type for potential reuse
    if not hasattr(self, "_complex_types"):
        self._complex_types = {}
    self._complex_types.setdefault(subcommand, {})[type_name] = _complex_type

    return _complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalize args to an iterable of key/value pairs.
    # Accept a list of tuples, dictionary, or list of strings.
    def _iter_args(arg_list):
        if isinstance(arg_list, dict):
            for k, v in arg_list.items():
                yield k, v
        elif isinstance(arg_list, list):
            for item in arg_list:
                if isinstance(item, tuple) and len(item) == 2:
                    yield item[0], item[1]
                elif isinstance(item, str):
                    # Treat a lone string as a flag with a boolean True
                    yield item, True
                else:
                    # Skip unrecognized formats
                    continue
        else:
            # Unsupported type, yield nothing
            return

    for key, value in _iter_args(args):
        # Normalize key to a string if not already
        if not isinstance(key, str):
            continue
        if key.startswith('control_'):
            # Strip the prefix for clarity, but keep the full key for use
            control_args[key] = value
        elif key.startswith('custom_'):
            # Convert custom variable to nested format by removing the prefix
            nested_key = key[len('custom_') :]
            nested_args[nested_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        if args is None:
            return {}, {}

        # Normalize args into a flat dictionary
        if isinstance(args, dict):
            flat_args = dict(args)  # shallow copy
        elif isinstance(args, (list, tuple)):
            flat_args = {}
            for a in args:
                if isinstance(a, dict):
                    flat_args.update(a)
        else:
            # Unsupported type; return empty dicts
            return {}, {}

        control_args = {}
        nested_args = {}

        for key, val in flat_args.items():
            # Detect control arguments by a prefix (e.g., 'control_')
            if isinstance(key, str) and key.lower().startswith("control_"):
                control_args[key] = val
            else:
                nested_args[key] = val

        return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into.
    :param extra_vars: List of extra-vars (or a single dict) that will be merged
                       into ``vars_dict``. Keys in ``extra_vars`` override
                       those in ``vars_dict``.
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("`vars_dict` must be a dictionary")

    if extra_vars is None:
        # Nothing to merge; return the original dictionary.
        return vars_dict

    # If a single dictionary is provided, merge it directly.
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # If a sequence (list/tuple) is provided, merge each individual dictionary.
    if isinstance(extra_vars, (list, tuple)):
        for elem in extra_vars:
            if isinstance(elem, dict):
                vars_dict.update(elem)
            else:
                raise ValueError(
                    "Each element of `extra_vars` must be a dictionary"
                )
        return vars_dict

    # Unsupported type for extra_vars.
    raise ValueError(
        "`extra_vars` must be a dict, a list, or a tuple of dicts"
    )

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        vars_dict = {}
    if extra_vars is None:
        return vars_dict
    # Ensure we have an iterable of dicts
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    for ext in extra_vars:
        if isinstance(ext, dict):
            vars_dict.update(ext)
        else:
            raise TypeError(f"Expected a dict in extra_vars, got {type(ext).__name__}")
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # Support a single dict or a list of dicts
    if isinstance(extra_vars, dict):
        items = [extra_vars]
    elif isinstance(extra_vars, (list, tuple)):
        items = extra_vars
    else:
        raise ValueError("extra_vars must be a dict or a list/tuple of dicts")

    for ev in items:
        if not isinstance(ev, dict):
            raise ValueError("Each item in extra_vars must be a dict")
        vars_dict.update(ev)

    return vars_dict

