        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if vars_dict is None:
            vars_dict = {}
        if not extra_vars:
            return vars_dict

        for extra in extra_vars:
            if isinstance(extra, dict):
                # Directly update the dictionary (override existing keys)
                vars_dict.update(extra)
            elif isinstance(extra, (list, tuple)):
                # Treat as a sequence of key/value pairs
                for kv in extra:
                    if isinstance(kv, (list, tuple)) and len(kv) == 2:
                        key, value = kv
                        vars_dict[key] = value
                    else:
                        # Attempt to parse a "key=value" string
                        try:
                            key, value = str(kv).split("=", 1)
                            vars_dict[key] = value
                        except Exception:
                            # Skip malformed entries
                            continue
            else:
                # Attempt to parse a single "key=value" string
                try:
                    key, value = str(extra).split("=", 1)
                    vars_dict[key] = value
                except Exception:
                    # Skip if not parseable
                    continue

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    result = dict(vars_dict)  # copy to avoid mutating input

    if not extra_vars:
        return result

    if isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                result.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                result[item[0]] = item[1]
            else:
                raise ValueError(
                    "Each element of extra_vars list must be a dict or a key/value pair"
                )
        return result

    if isinstance(extra_vars, dict):
        result.update(extra_vars)
        return result

    raise ValueError("extra_vars must be a dict or a list of dicts/key-value pairs")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    command = ["ansible-playbook"]

    if verbose:
        # Add verbosity flags (e.g., -vvv)
        command.append("-" + "v" * verbose)

    if ansible_args:
        for key, val in ansible_args.items():
            if val is True:
                command.append(f"--{key}")
            elif val is False:
                # skip false boolean options
                continue
            else:
                command.append(f"--{key}={val}")

    if extra_vars:
        try:
            import json
            extra_vars_str = json.dumps(extra_vars)
        except Exception:
            extra_vars_str = str(extra_vars)
        command.extend(["--extra-vars", extra_vars_str])

    command.append(playbook_path)

    # Determine where to execute the playbook
    cwd = None
    if hasattr(ir_workspace, "root"):
        cwd = ir_workspace.root
    elif hasattr(ir_workspace, "path"):
        cwd = ir_workspace.path

    result = subprocess.run(command, capture_output=True, text=True, cwd=cwd)

    if result.returncode != 0:
        raise RuntimeError(f"ansible-playbook failed with return code {result.returncode}:\n{result.stderr}")

    return result.stdout

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the initial command list
    command = ["ansible-playbook", playbook_path]

    # Verbosity handling – if not provided, default to -v
    if verbose is not None:
        # Accept int or string that looks like a numeric count
        try:
            count = int(verbose)
            if count > 0:
                command.append("-" + "v" * count)
            else:
                command.append("-v")
        except Exception:
            # Fallback to the literal string if conversion fails
            command.append(verbose)
    else:
        command.append("-v")

    # Add extra vars if supplied
    if extra_vars:
        ev = " ".join(f"{k}={v}" for k, v in extra_vars.items())
        command.extend(["--extra-vars", ev])

    # Append any extra ansible-playbook arguments
    if ansible_args:
        for flag, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(flag)
            else:
                command.extend([flag, str(value)])

    # Execute the command in the workspace directory
    result = subprocess.run(
        command,
        cwd=ir_workspace.path,
        capture_output=True,
        text=True
    )

    # Raise an error if the command failed
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook exited with {result.returncode}\nstdout: {result.stdout}\nstderr: {result.stderr}"
        )

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Mapping from parser_name to argument specifications.
    # Each spec is a dict mapping argument names to a type or a callable
    # that knows how to convert a string value.
    # Example:
    #   {
    #       'main': {'port': int, 'debug': bool, 'hosts': list, 'config': Path},
    #       'virsh': {...}
    #   }
    # The actual mapping is expected to be defined elsewhere in the class.
    specs = getattr(self, "_arg_specs", {})

    # If we have no specifications for this parser, nothing to do.
    if parser_name not in specs:
        return values_dict

    # Retrieve the arg spec for this parser.
    arg_spec = specs[parser_name]

    for arg_name, convert_func in arg_spec.items():
        if arg_name not in values_dict:
            continue
        raw_value = values_dict[arg_name]

        # If raw_value is already not a string, skip conversion.
        if not isinstance(raw_value, str):
            continue

        # Determine the conversion function.
        # If convert_func is a type (e.g., int, float), use it directly.
        # If it has a 'convert' method, use that.
        # Otherwise, try calling it as a callable.
        converter = None
        if isinstance(convert_func, type):
            converter = convert_func
        elif hasattr(convert_func, "convert"):
            converter = convert_func.convert
        elif callable(convert_func):
            converter = convert_func

        # Perform the conversion if a converter is found.
        if converter is not None:
            try:
                # For booleans, handle common string representations.
                if converter is bool:
                    values_dict[arg_name] = raw_value.lower() in ("true", "1", "yes", "y")
                else:
                    values_dict[arg_name] = converter(raw_value)
            except Exception:
                # If conversion fails, keep the original string value.
                values_dict[arg_name] = raw_value

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser instance, assume it is stored as an attribute of the same name
    parser = getattr(self, parser_name, None)
    if parser is None:
        raise AttributeError(f"Parser '{parser_name}' not found on {self!r}")
    # Iterate over each action defined in the parser
    for action in getattr(parser, "_actions", []):
        dest = action.dest
        # Skip the help action and any other path that doesn't correspond to a real argument
        if dest == "help":
            continue
        # If a value was supplied for this argument, attempt to cast it
        if dest in values_dict:
            raw_val = values_dict[dest]
            # If the raw value is already the expected type, no need to convert
            if action.type is None or isinstance(raw_val, action.type):
                continue
            try:
                # Attempt a direct conversion
                values_dict[dest] = action.type(raw_val)
            except Exception:
                # For boolean store_* actions, try a simple boolean conversion
                if getattr(action, "const", None) is not None and isinstance(raw_val, str):
                    lower_val = raw_val.lower()
                    if lower_val in {"1", "true", "yes", "y"}:
                        values_dict[dest] = True
                    elif lower_val in {"0", "false", "no", "n"}:
                        values_dict[dest] = False
                    else:
                        # Fall back to the original value if conversion fails
                        values_dict[dest] = raw_val
                else:
                    # If we can't convert, keep the original string
                    values_dict[dest] = raw_val
    # Return the mutated dictionary for convenience
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Get the parser configuration (list of option objects)
    parser_opts = getattr(self, "parsers", {}).get(parser_name, {})
    if not parser_opts:
        return values_dict

    # Ensure we work on a shallow copy to avoid mutating the original dict
    values = dict(values_dict)

    for opt in parser_opts:
        name = getattr(opt, "name", None)
        if name is None or not isinstance(name, str):
            continue
        if name not in values:
            continue
        raw_value = values[name]
        # If the value is already of the target type, skip conversion
        if hasattr(opt, "target_type") and isinstance(raw_value, opt.target_type):
            continue

        # Try to convert using the option's convert method if available,
        # otherwise fall back to a no-op.
        try:
            if hasattr(opt, "convert") and callable(opt.convert):
                values[name] = opt.convert(raw_value)
            elif hasattr(opt, "target_type") and opt.target_type:
                values[name] = opt.target_type(raw_value)
            else:
                values[name] = raw_value
        except Exception:
            # If conversion fails, leave the original value untouched
            values[name] = raw_value

    return values

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser configuration
    parser = getattr(self, 'parsers', {}).get(parser_name)
    if parser is None:
        # No parser configuration found; nothing to transform
        return values_dict

    for key, opt in parser.items():
        # Only attempt conversion if the key exists in the provided dict
        if key not in values_dict:
            continue

        value = values_dict[key]
        if value is None:
            continue

        # Prefer a dedicated convert function; fall back to a type call
        convert_func = getattr(opt, 'convert', None)
        if convert_func is None:
            convert_func = getattr(opt, 'type', None)

        if callable(convert_func):
            try:
                values_dict[key] = convert_func(value)
            except Exception:
                # If conversion fails, keep the original string value
                pass
        else:
            # No conversion available; leave the value unchanged
            continue

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    spec_files = ['plugin.json', 'plugin.yml', 'plugin.yaml']
    spec_path = None
    for f in spec_files:
        full_path = os.path.join(plugin_dir, f)
        if os.path.isfile(full_path):
            spec_path = full_path
            break

    if not spec_path:
        return {}

    # Load the spec file into a dictionary
    try:
        with open(spec_path, 'r', encoding='utf-8') as fp:
            if spec_path.endswith('.json'):
                import json
                spec_data = json.load(fp)
            else:
                # For yaml/yml assume yaml module is already available
                import yaml
                spec_data = yaml.safe_load(fp)
    except Exception:
        return {}

    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, key))
            elif isinstance(v, list):
                for idx, item in enumerate(v):
                    sub_key = f"{key}.{idx}"
                    if isinstance(item, dict):
                        flat.update(_flatten(item, sub_key))
                    else:
                        flat[sub_key] = item
            else:
                flat[key] = v
        return flat

    return _flatten(spec_data)

